local _, GQ = ...

-- Quest story paragraphs, keyed by the exact English paragraph.
if GQ.ActiveLocale ~= "koKR" then
    return
end

local text = GQ.LocaleText
for k, v in pairs({
    ["Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge."] = "몇 주째 우리 농부와 상인들을 괴롭혀 온 날강도 개릭 패드풋이 수도원 동쪽, 다리 건너편 포도밭 근처 오두막에서 목격되었습니다.",
    ["Nothing like a day of boar hunting, eh? Though, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging."] = "멧돼지 사냥하기 좋은 날이군요, 안 그렇습니까? 하지만 이곳 콜드리지 계곡에는 멧돼지가 너무 많아서 오히려 재미가 덜하지요. 굳이 돌진하게 만들 필요도 없습니다.",
    ["I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."] = "저 고약한 늑대들이 정말 싫습니다! 하지만 늑대 스테이크는 아주 좋아하지요... 질긴 늑대 고기를 가져오시면 쓸모 있는 물건으로 바꿔 드리겠습니다.",
    ["You look as though you might need something to keep your hands warm, hm? I'll tell you what would help: a pair of nice, warm gloves."] = "손을 따뜻하게 해 줄 무언가가 필요해 보이는군요? 도움이 될 만한 게 있습니다. 따뜻하고 좋은 장갑 한 켤레 말입니다.",
    ["Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\" He drove off the beast, but not before it mauled him savagely."] = "힐델브는 일기에 \"거대한 얼음발톱곰\" 맹기발톱에게 습격당했다고 적었습니다. 그는 짐승을 쫓아냈지만, 그 전에 크게 물어뜯기고 말았습니다.",
    ["The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies! So before she comes to our fields...Princess must die!"] = "브랙웰 가족에게는 상을 받은 돼지 프린세스가 있습니다. 이 암퇘지는 어마어마하게 큰데, 몰래 이쪽으로 넘어와 내 채소를 먹어 치워서 그렇게 된 겁니다! 그러니 프린세스가 우리 밭에 오기 전에... 프린세스를 없애야 합니다!",
    ["I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace. Don't ask me how it got there...it wasn't me!"] = "파고딥 광산 근처에서 놀다가, 제가 그, 음... 그러니까 할머니의 목걸이를 봤어요. 어떻게 거기 있었는지는 묻지 마세요... 제가 한 거 아니에요!",
    ["We believe they are hiding out in the Dagger Hills, plotting their next move. Slay the wretches in the name of The People's Militia."] = "놈들은 단검 언덕에 숨어 다음 행동을 꾸미고 있는 것으로 보입니다. 민병대의 이름으로 그 비열한 놈들을 처단하십시오.",
    ["Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"] = "이곳에 무슨 일이 벌어졌는지 보십시오! 이 땅은 한때 선량한 농부들이 살던 곳이었습니다. 그런데 저주받을 도둑놈들이 모두 쫓아냈지요. 나는 빼고 말입니다!",
    ["Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."] = "앞서 하신 조사로 에코 능선 광산을 소탕해야 한다는 사실이 입증되었습니다. 광산으로 돌아가 코볼트를 몰아내는 일을 도우십시오. 지체하지 마십시오.",
    ["For your shrewdness and valor, I have a marker here that is good for one piece of armor. I want you to take it to Sara Timberlain at the Eastvale Logging Camp."] = "당신의 영리함과 용맹에 보답하여, 방어구 한 점과 교환할 수 있는 증표를 드리겠습니다. 이것을 이스트베일 벌목 야영지의 사라 팀버레인에게 가져가십시오.",
    ["I must warn you, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home."] = "미리 경고하겠습니다. 이 일은 우리끼리만 알고 있어야 합니다. 사티로스 때문에 이미 충분히 망신을 당했는데, 이번 일은 너무 가까운 곳에서 벌어졌습니다.",
    ["We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."] = "한밤중에 비명이 들렸습니다. 그리고 아침에 보니 역시나 숫양 두 마리가 사라져 있었습니다. 바가쉬라는 그 비열한 짐승이 우리 생계를 노리고 있습니다.",
    ["I'm on a quest, a quest to make the perfect stout. I know I can do it -- brewing's in my blood. I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east."] = "저는 완벽한 스타우트를 만들겠다는 목표를 가지고 있습니다. 할 수 있다는 걸 압니다. 양조는 제 핏속에 흐르고 있으니까요. 알맞은 제조법만 찾으면 됩니다... 서리갈기 트롤들이 동쪽 언덕 높은 곳에서 반짝풀이라는 식물을 기르고 있습니다.",
    ["Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."] = "놈리건 사태를 더 분석해 본 결과, 우리가 트로그를 없애는 데 실패했을 뿐 아니라 놈 종족 대부분을 끔찍하고 정신 나간 사악한 나환자 노움으로 만들어 버린 것으로 보입니다.",
    ["The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!"] = "동쪽의 은빛시내 광산은 오래전에 말라 버렸습니다. 광부 연맹이 저장소로 바꿔 놓았는데, 이제 코볼트들이 들어와서 훌륭한 드워프 도구에 더러운 손을 대고 있습니다!",
    ["One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power."] = "우리가 겪는 가장 큰 어려움 중 하나는 생존에 필요한 천연자원을 얻는 일입니다. 얼라이언스의 힘이 절정이었을 때조차 금은 귀했습니다.",
    ["Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."] = "집행관 자이간드가 당신이 붉은십자군을 처치하고 다닌다고 하더군요. 티리스팔 숲은 그들로 득실거립니다.",
    ["The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."] = "북쪽 가렌의 소굴 남서쪽에 있는 집단 묘지는 역병이 처음 닥쳤을 때 티리스팔이 입은... 엄청난... 수의 사망자를 수용하기 위해 만들어졌습니다.",
    ["The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."] = "아가만드 제분소 지역은 스컬지의 거점이 되었습니다. 그들의 가장 강력한 거점은 아가만드 가문 지하묘지로, 그곳에 해골 지휘관 다르골 대장이 본부를 차렸습니다.",
    ["Wanted: Maggot Eye! A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken. This despicable villain has been stealing corpses for use by the Lich King's army."] = "현상 수배: 구더기눈! 놀 기준으로도 추악한 이 짐승은 포세이큰에 대한 죄로 사형을 선고받았습니다. 이 비열한 악당은 리치 왕의 군대에 쓰이도록 시체를 훔치고 있습니다.",
    ["According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."] = "베라르드의 일지에 따르면 호수 잠복자와 포복자에게서 얻은 이끼가 새로운 역병을 빚는 우리의 연구에 쓸모가 있을지 모릅니다. 그 짐승들은 동쪽 로다미어 호수의 섬에 서식합니다.",
    ["As my understanding of Arugal's magic grows so does my disdain for the hapless fool. I am close to completing my research on his so called remedy."] = "아루갈의 마법을 이해하면 할수록 그 한심한 바보에 대한 경멸도 커집니다. 그의 이른바 치료법에 대한 연구가 거의 끝나 갑니다.",
    ["It's so cold, now. The Plague of Undeath crawls through my veins like an icy serpent. The Mindless State will be upon me soon. But no doomed destiny will prevent me from serving our Dark Lady."] = "이제는 너무 춥군요. 언데드 역병이 얼음 뱀처럼 내 혈관 속을 기어갑니다. 곧 정신을 잃은 상태가 닥칠 겁니다. 하지만 어떤 비참한 운명도 어둠의 여왕을 섬기려는 나를 막을 수는 없습니다.",
    ["I now present you with the Water of the Seers. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire."] = "이제 선견자의 물을 드리겠습니다. 준비가 되면 부족의 모닥불 옆에서 이 물을 마시십시오. 성스러운 물을 마시고 나면 불 앞에 환영이 나타나기까지 잠시 시간이 걸립니다.",
    ["Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."] = "이제 거미 독을 얻었으니 연구할 살아 있는 표본이 필요합니다. 안타깝게도 살아 있는 거대 거미를 잡아 오라는 건, 어린 당신에게는 무리한 부탁이겠지요.",
    ["A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival."] = "사냥의 방식에 능숙한 타우렌은 사냥감이 단순한 전리품이 아님을 압니다. 평원의 짐승들은 우리가 살아가는 수단을 줄 뿐입니다.",
    ["We are hunters. Down below in Mulgore there is a mighty kodo named Arra'chea."] = "우리는 사냥꾼입니다. 아래쪽 멀고어에는 아라체아라는 강대한 코도가 있습니다.",
    ["The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead."] = "가장 먼저 할 일은 당신의 배짱을 길러 주는 것입니다. 불모의 땅으로 보내 코도를 사냥하게 할 수도 있겠지만, 솔직히 말해 당신은 죽은 것보다 산 것이 우리에게 더 쓸모 있습니다.",
    ["Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted."] = "당신이 나를 위해 해 준 일을 보니 마음이 굳세집니다. 이렇게 쉽게 쓰러질 수는 없습니다! 견뎌내야 합니다! 하지만 도움 없이는 굴로 돌아가는 길을 걸을 수가 없습니다.",
    ["Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here."] = "강한 전사도 서툰 초보자도 전갈 모양 괴물의 독침에 쓰러졌습니다. 여기서 북서쪽에 가면 전갈 모양 괴물이 아주 많습니다.",
    ["Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic. It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven."] = "점술로 보니, 불타는 칼날 소굴 깊은 곳에 짐승과 흑마법이 지키는 힘의 물건이 숨겨져 있습니다. 불타는 칼날 메달이라는 물건인데, 당신의 다음 임무는 그것을 찾아 소굴에서 가져오는 것입니다.",
    ["One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep."] = "가장 관찰력이 뛰어난 정찰병 한 명이 프라우드무어 함대의 잔해가 아직도 듀로타 해안, 티라가드 요새 바로 동쪽에 남아 있다는 소식을 가져왔습니다.",
    ["... your timing is perfect. I just hope I can compliment your haste as well. I was careless while fighting a few of the venomtails nearby, and one of them stung me deeply."] = "... 때맞춰 오셨군요. 당신의 신속함도 칭찬할 수 있으면 좋겠습니다. 근처에서 독꼬리 몇 마리와 싸우다 방심했고, 그중 한 마리에게 깊이 쏘였습니다.",
    ["Lower your voice. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag."] = "목소리를 낮추십시오. 콜카르 켄타우로스가 서쪽 능선 바로 너머 콜카르 바위산에 있습니다.",
    ["The witchdoctor Zalazane dwells on the Echo Isles to the east. They are the isles we once called home. From there he sends his trolls to the mainland, to hex our people and drag more of them under his sway."] = "주술사 잘라자네는 동쪽 메아리 섬에 살고 있습니다. 그곳은 우리가 한때 고향이라 부르던 섬들입니다. 그는 거기서 트롤들을 본토로 보내 우리 동족에게 저주를 걸고 더 많이 자기 휘하로 끌어들입니다.",
    ["We cannot allow the Burning Blade a foothold in Durotar! We must destroy them before their evil festers!"] = "불타는 칼날이 듀로타에 발판을 마련하게 둘 수는 없습니다! 그들의 악이 곪기 전에 파괴해야 합니다!",
    ["please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River."] = "부탁입니다, 도와주실 수 있겠습니까? 제 아들 크론이 며칠 전 사냥하러 나갔는데 아직 돌아오지 않았습니다. 사우스퓨리 강을 따라 악어를 사냥하러 서쪽 불모의 땅으로 갔습니다.",
    [". The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock. Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars."] = "불타는 칼날이 오그리마 동쪽 해골 바위라는 동굴을 점령했습니다. 그 동굴 안에서 그들은 사악한 의식을 치르며 작열의 목걸이로 제 살을 태웁니다.",
    ["You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff."] = "당신에게서는 장래성이 느껴지며, 부족에게 실력을 증명하게 될 것입니다. 어쩌면 머지않아 위대한 도시 썬더 블러프에 환영받는 날이 올지도 모릅니다.",
    ["Greetings, young one. You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt. May you bring honor to your clan!"] = "어서 오게, 젊은이. 눈빛이 반짝이는군. 평원으로 돌아가 사냥하고 싶어 안달이 난 것이 보여. 그대의 부족에 영예를 가져오기를!",
    ["And again, it is your task to perform the ritual of cleansing. Go to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual."] = "이번에도 정화 의식을 치르는 것이 그대의 임무입니다. 마을 북쪽의 천둥뿔 우물로 가서 의식에 천둥뿔 정화 토템을 사용하십시오.",
    ["According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands."] = "당신이 마차에서 구해 온 문서에 따르면, 벤처 회사는 우리를 이 땅에서 몰아내고 마음껏 약탈하려고 여러 계획을 세웠습니다.",
    ["my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him. I want to ask a favor of you while I finish tanning these leather straps."] = "오라버니가 곧 족장 블러드후프 앞에 서게 되는데, 그의 머리장식을 만들어 주는 것은 저의 영광입니다. 이 가죽끈 무두질을 마치는 동안 부탁 하나 드리고 싶습니다.",
    ["There are dwarves preparing a dig site to the northwest. They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings."] = "북서쪽에서 드워프들이 발굴 현장을 준비하고 있습니다. 그들은 땅속에 비밀이 있다고 생각하는데 그 말은 맞지만, 땅을 파헤치고 더럽히는 것은 그 가르침을 얻는 길이 아닙니다.",
    ["The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise...."] = "유령울음의 누더기 가죽에는 불타는 군단과 싸우다 입은 끔찍한 상처가 아직 남아 있습니다. 어쩌면 블러드후프 마을에서는 유령울음의 최후를 알아야 할지도 모르겠습니다....",
    ["He told me of its demonic red eyes, razor-sharp talons and venomous bite. As fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder."] = "그는 악마 같은 붉은 눈, 면도날처럼 날카로운 발톱, 독이 있는 이빨에 대해 말해 주었습니다. 공교롭게도 평원을 여행하다 그것과 마주쳤고, 어깨를 심하게 물렸습니다.",
    ["One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."] = "정찰병 한 명이 듀로타에서 오는 마차 행렬이 습격당하는 것을 목격했습니다. 범인은 정말로 가시멧돼지 칼갈기 부족이었습니다. 그중에서도 크리닉 스나르스나웃이 습격을 이끌고 있습니다.",
    ["While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."] = "내 물건을 전부 되찾고 싶지만, 그건 불가능하겠지요. 그래도 꼭 필요한 것이 몇 가지 있습니다! 보시다시피 관측소는 준비가 되었는데, 두 개의 렌즈 중 작은 쪽이 필요합니다.",
    ["The herbs of the Barrens are not quite like herbs in other lands. Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different."] = "불모의 땅의 약초는 다른 땅의 약초와 조금 다릅니다. 특성은 대체로 같지만, 이곳의 오아시스 물이 식물을 변화시켜서 아주 약간 다릅니다.",
    ["The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."] = "콜카르는 불모의 땅에서 호드의 영유권을 위협합니다. 그들의 병력을 줄여야 합니다. 그래서 현상금 임무를 하나 드리겠습니다.",
    ["Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."] = "어서 오십시오. 저는 관리인 일탈레인입니다. 그늘숲 골짜기에서 제가 맡은 임무는 자연의 균형이 유지되도록 하는 것입니다.",
    ["Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."] = "텔드랏실의 숲에서 무언가 사악한 일이 벌어지고 있습니다. 평화로운 퍼볼그가 살던 언덕 쪽을 길게 바라보십시오. 그들은 집을 버리고 옹이소나무 부족이라는 이름 아래 모이고 있습니다.",
    ["Thinning the younger population of creatures here in Shadowglen was a good start, but there is still work to be done. The resources of the forest will be depleted too quickly if the problem is not addressed."] = "이곳 그늘숲 골짜기의 어린 생물들을 솎아 낸 것은 좋은 시작이었지만, 아직 할 일이 남아 있습니다. 이 문제를 해결하지 않으면 숲의 자원이 너무 빨리 고갈될 것입니다.",
    ["The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire. I have prepared power stones that when placed near the Seed will disrupt its connection to the Legion."] = "악마의 씨앗은 불타는 군단의 강력한 도구입니다. 그것은 공포안개 봉우리 위, 악마의 불 제단 위에 있는 동굴에 놓여 있습니다. 제가 마력석을 준비했는데, 씨앗 근처에 놓으면 군단과의 연결을 끊을 수 있습니다.",
    ["In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home."] = "호수 남쪽 기슭 동굴에서 오크노스코울이라는 나무정령이 알아메스 호수를 터전으로 삼은 모든 생물에게 타락을 퍼뜨리고 있습니다.",
    ["Now the time has come to save the Druids of the Talon. If we fail now, they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual."] = "이제 발톱 드루이드를 구할 때가 되었습니다. 지금 실패하면 그들은 영원히 잠에 빠져 있을 것입니다. 깨움의 유물을 준비하고 의식을 진행하겠습니다.",
    ["I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."] = "저는 소규모 감시병 무리와 함께 이곳 신탁의 나무를 지키러 파견되었습니다. 공터 주변에 둥지를 튼 하피들로부터 말입니다.",
    ["Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble."] = "작은 나무정령들이 알아메스 호수 물가에 싹트고 있습니다. 이 싹들은 이미 어쩔 수 없는 듯하니, 문제를 일으킬 만큼 자라기 전에 땅에서 없애야 합니다.",
    [". A task I would ask of you. Have you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south."] = ". 부탁드릴 일이 있습니다. 아메스아란 폐허를 보셨습니까? 못 보셨다면 큰길 동쪽, 남쪽으로 조금 내려간 곳에 있습니다.",
    ["It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."] = "저의 감옥을 이룬 봉인은 가장 강력한 하이본 중 한 명의 솜씨로 만들어졌습니다. 이곳과 쌍을 이루는 남쪽 폐허 아메스아란에는 오늘날까지도 푸른색의 고대 불꽃이 남아 있습니다.",
    ["The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war."] = "동쪽 브램블블레이드 협곡의 전투멧돼지들이 우리 부족의 사냥터를 침범하고 있습니다. 우리와 전쟁 중인 강모 가시멧돼지들이 그들을 악랄하게 훈련시켰습니다.",
    ["My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need."] = "제 임무는 부상당한 전사들을 돌보고, 방어구와 옷을 짓고, 암흑 사제 사르비스가 필요로 하는 다른 일을 돕는 것입니다.",
    ["Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."] = "현상 수배: 호거. 거대한 놀 호거가 엘윈 남서쪽 숲을 배회하고 있습니다. 그를 생포하려는 모든 시도는 실패했습니다. 스톰윈드 군대는 이 놀에게 후한 현상금을 걸었습니다.",
    ["I hope you're here to lend us a hand. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception."] = "도와주러 오셨기를 바랍니다. 지난번 트로그의 공격 이후 우리에게는 모든 도움이 필요합니다. 그 녀석들이 온 땅에 나타나고 있다고 들었는데, 콜드리지 계곡도 예외가 아닌 모양입니다.",
    ["After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."] = "이 부적을 살펴보니 이제 무엇을 해야 할지 알겠습니다. 이것을 받아서 제가 부탁하는 대로 하십시오. 밴에틸 지하 굴의 가장 깊은 곳을 탐험해야 합니다.",
    ["Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest."] = "이제 당신에게 맡겨진 임무를 마쳐야 합니다. 방적돌기를 가지고 엘룬에게 사스라 부인의 제물을 바치십시오. 거대한 거미를 잠들게 하십시오.",
    ["Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."] = "옹이소나무 침략자들이 서쪽 밴에틸 지하 굴을 휩쓸고 있는 것이 목격되었습니다. 우리가 돕지 않으면 잠든 드루이드들은 자신의 운명도 모른 채 영원히 에메랄드의 꿈에 갇히게 될 것입니다.",
    ["- I have heard of you, newcomer. Perhaps it is you that will help us, where others have failed. We tauren have carved a home out of this land, but not without a cost."] = "- 당신에 대한 이야기는 들었소, 이방인. 다른 이들이 실패한 곳에서 어쩌면 당신이 우리를 도와줄지도 모르겠소. 우리 타우렌은 이 땅에 보금자리를 일구었지만, 그 대가가 없지는 않았소.",
    ["The antidote is ready. Please see that Iverron drinks it. There is something that you should know -- the antidote -- it will only remain viable for 5 minutes."] = "해독제가 준비되었습니다. 이베론이 꼭 마시도록 해 주십시오. 알아 두셔야 할 것이 있습니다. 이 해독제는 5분 동안만 효력이 유지됩니다.",
    ["You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine."] = "닐스 수사는 수도원 종탑에서 찾을 수 있을 겁니다... 자신의 포도주를 맛보기 좋아하는 곳이지요.",
    ["You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."] = "거기 당신! 쓸모 있는 일을 찾고 있다면 잘 들으십시오! 땅에서 막 나온 신병들이 데스넬로 가서 쓸 만한 장비를 찾아봐야 합니다.",
    ["You may have killed the raptors, but the silver they stole must be recovered! I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds."] = "랩터를 죽였을지 몰라도, 놈들이 훔친 은은 되찾아야 합니다! 보고에 따르면 랩터들이 래칫 남쪽, 랩터 서식지라고 알려진 곳에 큰 둥지 무리를 이루고 있다고 합니다.",
    ["You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."] = "너는 나의 부관 중 하나다! 준비하라. 곧 너를 부르겠다. 불타는 칼날에서 보낸 내 시간은 이제 거의 헛되이 되었지만, 그렇다고 다른 곳에서의 그림자 의회의 계획까지 무너져서는 안 된다.",
    ["Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."] = "알다시피 군단의 많은 수하들은 추종자들에게 선물을 내립니다. 그중 어떤 선물은 어둠의 여왕께서 그것을 가진 자들보다 자신의 손에 있는 편이 낫다고 여기십니다...",
    ["You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."] = "타우렌의 시신 아래에서 가방을 발견합니다. 트로그에게 공격당하는 동안 지키려 했던 것처럼 그의 팔에 아직도 꼭 쥐어져 있습니다.",
    ["Mellifluous liquid clear as a baby's tears Turns a lovely deep amber over the years But before we proceed to get lit to the hilt A barrel of charred oak must be built."] = "아기의 눈물처럼 맑은 달콤한 액체, 세월이 흐르면 아름다운 짙은 호박색으로 변하네. 하지만 흠뻑 취하기 전에, 그을린 참나무 통부터 만들어야 한다네.",
    ["Return to your own tribe and let them know of your victory here. Show them your trophy, and bask in the glory..."] = "당신의 부족에게 돌아가 이곳에서의 승리를 알리십시오. 전리품을 보여 주고 영광을 누리십시오...",
    ["When my life was ended upon the rocks, I had no clue what the afterlife held for me. The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off."] = "내 삶이 바위 위에서 끝났을 때, 저승이 나에게 무엇을 줄지 알지 못했습니다. 그날 밤 등대가 어두웠던 것은 늙은 머크아이가 등대지기의 가족을 쫓아냈기 때문입니다.",
    ["You have proven your loyalty to King Magni. And your hatred for the Dark Iron scum is as great as my own. There is a task I wish to complete myself but I am bound by honor to stay with Longbraid."] = "당신은 매그니 왕에 대한 충성을 입증했습니다. 그리고 검은무쇠 쓰레기에 대한 당신의 증오는 나만큼이나 큽니다. 내가 직접 해결하고 싶은 임무가 있지만, 명예 때문에 롱브레이드와 함께 남아야 합니다.",
    ["I find myself in quite a pinch here. The bottles are close to running dry. The latest booze shipment is long overdue. The orc invasion has been hell."] = "상당히 곤란한 처지에 놓였습니다. 병이 거의 바닥나고 있습니다. 최근 술 배송이 한참 늦어지고 있습니다. 오크 침공은 지옥 같았습니다.",
    ["I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire."] = "검은용 새끼의 배 비늘이 필요합니다. 아르거스가 골드샤이어에서 보내 준 신발값을 치러야 하거든요.",
    ["During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor."] = "지난 오크 침공 때 우리는 철을 녹여 총알과 칼, 갑옷을 만들 수밖에 없었습니다.",
    ["You have uncovered a dark threat to the land. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc."] = "당신은 이 땅에 도사린 어두운 위협을 밝혀냈습니다. 그 동굴에서 찾은 레조나이트 통에는 고게로크라는 잠든 대지의 존재가 들어 있습니다.",
    ["Targorr the Dread served under Gath'Ilzogg as supreme Executioner. His methods were ruthless, even by filthy orc standards. Men who fought bravely to defend the Kingdom were tortured on his whim."] = "공포의 타고르는 가스일조그 밑에서 최고 집행자로 일했습니다. 그의 수법은 더러운 오크 기준으로 보아도 잔혹했습니다. 왕국을 용감히 지키던 사람들이 그의 변덕에 따라 고문당했습니다.",
    ["the gnolls are still out there. I can hear their baying as they hunt in the hills above Lakeshire. And one cry is louder than the rest - Yowler, their leader."] = "놀들이 아직도 밖에 있습니다. 레이크샤이어 위쪽 언덕에서 사냥하며 울부짖는 소리가 들립니다. 그리고 그중 하나의 울음소리가 유독 큽니다. 그들의 우두머리 요울러입니다.",
    ["our scouts have identified the leader of this recent Trogg incursion. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug."] = "우리 정찰병들이 이번 트로그 침입의 우두머리를 파악했습니다. 모단 호수의 이 짐승들은 그라우머그라는 족장을 따르는 것으로 보입니다.",
    ["By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."] = "텔사마 치안판사의 명령: 텔사마 마을, 스톤래프트 댐, 발굴 현장에 대한 공격의 우두머리이자 조율자로 추정되는 오우거 촉술을 어떠한 수단을 써서라도 사살하라는 수배령이 내려졌다.",
    ["The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."] = "이 매춘부! 이 돼지 같은 년! 케나타는 아직 살아 있습니다. 가족은 건강하고 번창하는데 나는 고통받고 있습니다. 포세이큰이라니! 내 가족은 사라졌습니다. 역병이 데려갔습니다.",
    ["Many of my friends perished that horrible day when the mine tunnel caved in. If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them."] = "그 끔찍한 날 광산 터널이 무너져 내렸을 때 내 친구들 중 많은 이가 죽었습니다. 모험 중에 문브룩 광산의 그 구역에 가게 된다면, 그들의 신원을 알 수 있는 단서가 있는지 살펴봐 주십시오.",
    ["Edwin VanCleef must be assassinated. While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."] = "에드윈 밴클리프는 암살되어야 합니다. 누구에게든 사형 선고를 내리는 것은 슬픈 일이지만, 웨스트폴 사람들의 더 큰 이익을 위해 밴클리프를 영원히 잠재워야 합니다.",
    ["Travel to his cottage just north of town, and execute Stalvan, once and for all. When the deed is done, travel to Madame Eva's and show her his family ring."] = "마을 북쪽에 있는 그의 오두막으로 가서 스탈반을 처형하십시오. 일이 끝나면 이바 부인의 집으로 가서 그의 가문 반지를 보여 주십시오.",
    ["It's no secret that the trademark of the Defias Gang is their Red Bandanas. But we've learned that the material from which these bandanas are made signifies the member's rank."] = "데피아즈단의 상징이 붉은 두건이라는 것은 비밀이 아닙니다. 하지만 이 두건의 소재가 단원의 계급을 나타낸다는 사실을 알아냈습니다.",
    ["I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!"] = "위대한 바르톨로가 세계적으로 유명하고 얼라이언스 전역에 명성이 자자한 설인 털가죽 망토를 만들어 드리겠습니다!",
    ["You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."] = "딱 맞춰 오셨군요! 파이어우드 회의가 곧 돌아올 겁니다. 아루갈은 성채에서 다른 일을 처리하고 있습니다. 그는 회의를 한낱 꼭두각시로 삼아 파이어우드의 정신 나간 하수인들을 통제합니다.",
    ["Here you go. Bring this message to Master Carevin. A few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today."] = "자, 받으십시오. 이 전갈을 카레빈 장로에게 가져가십시오. 당신 같은 사람이 몇 명만 더 있어도 야경대보다 수가 많아질 겁니다! 그러면 오늘 우리 몇 명이 이어 가고 있는 일을 끝낼 수 있을지도 모릅니다.",
    ["The keg fizzles slightly."] = "통이 살짝 부글거립니다.",
    ["Just before the invasion I uncovered a large tablet called the Goaz Stone. The translated text breaks off in 4 places. The text speaks of a \"divine plan\" and a \"doomed prophecy.\" I fear we are running out of time."] = "침공 직전에 저는 고아즈 석판이라는 커다란 석판을 발견했습니다. 번역된 글은 4곳에서 끊깁니다. 글은 \"신성한 계획\"과 \"저주받은 예언\"에 대해 이야기합니다. 우리에게 시간이 얼마 남지 않은 것 같아 두렵습니다.",
    ["I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind."] = "왕께 올릴 보고서를 준비했습니다. 당신이 직접 발견한 내용에 대한 설명과 함께 그것을 전달하는 것이 좋겠습니다. 걱정하지 마십시오. 스톰윈드 시민을 위한 임무를 다한 당신을 왕께서 틀림없이 치하하실 겁니다.",
    ["I can't lift the curse from the Eye of Paleth."] = "저는 팔레스의 눈에 걸린 저주를 풀 수 없습니다.",
    ["After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw. It depicts a young, long-haired Paladin with hammer upraised."] = "진흙에서 통을 끌어내 열어 보니 고운 짚에 싸인 은빛 조각상이 나옵니다. 망치를 치켜든 긴 머리의 젊은 성기사의 모습입니다.",
    ["Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery. His time in this land is drawing to an end..."] = "모벤트 펠은 동쪽 언덕 위, 레이븐 힐 묘지를 내려다보는 집에 있는 소굴에 숨어 있습니다. 이 땅에서 그의 시간은 끝나가고 있습니다...",
    ["We have a real infestation problem to the west. Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!"] = "서쪽에 심각한 해충 문제가 생겼습니다. 터널쥐 코볼트들이 산기슭에 들어와 굴을 파고 우리 땅을 오물로 더럽히고 있습니다!",
    ["Ready to go? First, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me."] = "갈 준비가 되셨습니까? 먼저 이 화약을 아이언밴드에게 가져가야 합니다. 저 혼자 들기엔 많고, 이 지역은 위험할 수 있습니다. 게다가 검은무쇠가 또 무슨 수작을 부릴지 누가 알겠습니까.",
    ["Valdred, once my good friend, was my wife's murderer. Although I am incapable of grieving, I do yearn for revenge. If you kill Valdred and bring me his cursed hands, then I will reward you."] = "발드레드는 한때 나의 좋은 친구였지만 내 아내의 살인자였습니다. 나는 슬퍼할 수 없는 몸이지만 복수를 갈망합니다. 발드레드를 죽이고 그의 저주받은 손을 가져오면 보상하겠습니다.",
    ["In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence."] = "그림자송곳니 성채 공격을 준비하며 죽음추적자 두 명이 정보를 수집하러 성채로 파견되었습니다.",
    ["Sure enough, deep within the Old Jug there is another clue to Sander's treasure."] = "역시나, 낡은 술병 깊숙한 곳에 샌더의 보물에 대한 또 다른 단서가 있습니다.",
    ["At last, friends of the Alliance! Help... please... The last thing I remember these foul Orcs overpowered our regiment. Most the men were killed."] = "드디어 얼라이언스의 친구들이군요! 도와주세요... 제발... 제가 기억하는 마지막 장면은 이 더러운 오크들이 우리 연대를 압도한 것입니다. 대부분의 병사들이 죽었습니다.",
    ["An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him."] = "강력한 대마법사가 마력선 결절점의 재가동을 감독하고 있습니다. 그들이 이룬 진척을 보면, 그들을 막을 유일한 희망은 그를 처치하는 것입니다.",
    ["Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed."] = "툴이 언젠가 말해 주기를, 오래전 그와 두 동료가 마법사들이 각자 가지고 있던 수련용 지팡이를 엮어 마법 지팡이를 만들었다고 합니다.",
    ["Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle. You must again go to the Isle and destroy Thule Ravenclaw."] = "이제 은빛소나무 숲에 있는 스컬지의 거점, 펜리스 섬을 공격할 때입니다. 다시 섬으로 가서 툴 레이븐클로를 없애십시오.",
    ["The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."] = "데피아즈단 전선은 끊임없이 변합니다. 저는 꽤 오랫동안 그들의 움직임을 추적해 왔습니다. 덧붙이자면, 단원 중 다수는 그들이 쓰는 붉은 가죽 두건으로 추적할 수 있다는 사실을 알아냈습니다.",
    ["The Embalmer is a name told in one of our children's stories. He was a kindly alchemist, driven mad by the death of his wife, Eliza. To restore her, he used dark magic to place his own heart within the bosom of his dead spouse."] = "방부 처리사는 우리 아이들의 이야기에 나오는 이름입니다. 그는 아내 엘리자의 죽음으로 미쳐 버린 자상한 연금술사였습니다. 그녀를 되살리기 위해 그는 암흑 마법으로 자신의 심장을 죽은 아내의 가슴에 넣었습니다.",
    ["I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him..."] = "저는 견습생을 늪지로 보내 이름난 저습지 거대 악어의 가죽을 벗겨 오게 했습니다. 그가 돌아오지 않아서 찾으러 나갔지요...",
    ["While you were down there I happened to notice that one of those beasts stood out from the rest. He was bigger and more menacing. I bet he's the one who led the others here to cause the disruption to the dig site."] = "당신이 아래에 있는 동안, 그 짐승들 중 하나가 유독 눈에 띄는 것을 보았습니다. 더 크고 더 위협적이었습니다. 다른 놈들을 이끌고 와서 발굴 현장을 어지럽힌 것은 분명 그놈일 겁니다.",
    ["My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec. But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul."] = "형 퀸과 저는 은빛소나무 숲을 정찰하고 상급 집행관 하드렉에게 보고하라는 임무를 받았습니다. 하지만 멀리 가지 못했습니다. 이 농장을 지나던 중 구울 아이바르 더러운 놈에게 공격당했습니다.",
    ["Dangerous! The following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia: Clerk Horrace Whitesteed."] = "위험! 다음 힐스브래드 인간들은 위험 인물로 지정되었으며 상급 집행관 다르타리아가 현상금을 걸었다: 서기 호라스 화이트스티드.",
    ["I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad. So jealous I am..."] = "다르타리아가 당신을 힐스브래드 인간들과의 전쟁에 징집했다고 들었습니다. 정말 부럽군요...",
    ["Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."] = "아... 힐스브래드에는 꽃이 피고 공기는 이토록 신선하고 상쾌합니다. 이 모든 비참함 속에 빠져 있지 않을 수가 없군요. 더러운 창문 밖을 내다보며 우리의 새로운 역병이 이 세상에 마땅한 죽음을 가져올 날을 고대합니다.",
    ["A mudsnout composite? Absolutely brilliant! Why didn't I think of that? Let me contribute my colloid of decay to this devilish brew."] = "진흙주둥이 합성물이라니요? 정말 훌륭합니다! 왜 나는 그 생각을 못 했을까요? 제 부패의 콜로이드도 이 악마 같은 혼합물에 보태겠습니다.",
    ["High Executor Darthalia sent me to keep watch of Dun Garok from a distance. I had set up camp just out of sight. But when morning came and I had to boil water, I left to gather firewood."] = "상급 집행관 다르타리아가 저를 멀리서 던 가록을 감시하라고 보냈습니다. 눈에 띄지 않는 곳에 야영지를 차렸지요. 그런데 아침이 되어 물을 끓여야 해서 땔감을 구하러 나갔습니다.",
    ["Ain't nothin' that irks me more than losin' these here beautiful horses."] = "이 아름다운 말들을 잃는 것만큼 나를 화나게 하는 일은 없습니다.",
    ["I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate."] = "저는 이전 치안판사가 암살된 후 최근 임명된 사우스쇼어의 새 치안판사입니다.",
    ["Take this sealed commendation to Varimathras in the Undercity."] = "이 봉인된 추천서를 언더시티의 바리마티아스에게 가져가십시오.",
    ["Here is the final challenge that I will put forth. We've been tracking an elusive tiger for weeks."] = "이것이 제가 내는 마지막 도전입니다. 우리는 몇 주째 종잡을 수 없는 호랑이 한 마리를 추적해 왔습니다.",
    ["You've almost proven yourself to be a master hunter of panthers."] = "당신은 표범 사냥의 달인임을 거의 입증하셨습니다.",
    ["For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line."] = "이 일에는 최고급 늙은 악어 가죽만 씁니다. 더 질기고, 드리즐릭 엑셀시어 제품군을 이루는 무늬와 장식을 더하기에 더 나은 캔버스랄까요.",
    ["There is but one final reagent needed to complete the enchantment. In the south, towards the western coast, high above the bluffs, lies a Holy Spring."] = "마법 부여를 완성하는 데 필요한 마지막 재료가 하나 남았습니다. 남쪽, 서쪽 해안 쪽 절벽 높은 곳에 성스러운 샘이 있습니다.",
    ["Avast! Who goes there? Argh, I am but useless without me special enchanted eye. Bad enough to have lost me eyes in battle in the first place!"] = "어이! 거기 누구냐? 아아, 내 특별한 마법의 눈이 없으면 나는 쓸모없다네. 애초에 전투에서 눈을 잃은 것만으로도 충분히 괴로운데!",
    ["Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill."] = "정글에서 그토록 적극적인 모습을 보여 주셨으니, 저조차도 죽이지 못한 사나운 랩터 이야기를 해 드리지요.",
    ["So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for."] = "그러니까 제단 같은 것을 찾고 계신 거군요? 저는 아버지처럼 트롤 유적에 정통하지는 않지만, 찾으시는 그 섬 근처에 가라앉은 트롤 도시가 있다는 이야기는 들었습니다.",
    ["Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key."] = "이 기록 어디에도 이병 토르센에 대한 언급은 없지만, 헤롯의 장부 한 권의 제본 속에 작은 황동 열쇠가 숨겨져 있습니다.",
    ["While you were gone I fixed the pot you brought me. I even added an extra steam whistle, and look! There's a new chopper at the bottom that'll cut through leg bones!"] = "당신이 없는 동안 가져오신 냄비를 고쳐 놓았습니다. 증기 호루라기도 하나 더 달았고, 보십시오! 바닥에 정강이뼈도 썰어 버릴 새 칼날도 달았습니다!",
    ["Kurzen may be dead, but...that which drove him to evil still lives! Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn."] = "쿠르젠은 죽었을지 몰라도... 그를 악으로 몰아넣은 것은 아직 살아 있습니다! 연구 끝에 알아낸 것이 있습니다. 오우거 마법사 마이조스가 가시덤불 협곡 동쪽 산맥의 오우거 언덕에 살고 있습니다.",
    ["The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold! Please, you must help me!"] = "벤처 회사는 가시덤불 협곡 곳곳에서 사업을 벌여, 저처럼 열심히 일하는 고블린이 정직하게 금을 벌지 못하게 막고 있습니다! 제발, 저를 도와주셔야 합니다!",
    ["Negolash is a hungry giant. When the giants destroyed our ship, Negolash went straight for my kitchen. He wasn't hungry for crew like the other giants."] = "네골라쉬는 굶주린 거인입니다. 거인들이 우리 배를 부쉈을 때, 네골라쉬는 곧장 제 주방으로 달려왔습니다. 다른 거인들처럼 선원을 먹고 싶어 하지는 않았지요.",
    ["Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay. He is exiled from his tribe. Why? Well..."] = "추방자 잔질은 추종자들과 함께 무법항 북동쪽 주부왈 유적과 아보라즈 유적에서 지내고 있습니다. 그는 부족에게서 추방당했습니다. 왜냐고요? 글쎄요...",
    ["We must find if Yenniku is dead. Slay the Bloodscalp Headhunters and take from them their Shrunken Heads. You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them."] = "예니쿠가 죽었는지 알아내야 합니다. 피 두개골 부족 사냥꾼들을 처치하고 그들에게서 쪼그라든 머리를 빼앗으십시오. 아주 많은 머리를 모아 오셔야 하며, 그중에 예니쿠의 머리가 없는지 제가 확인하겠습니다.",
    ["I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."] = "정신의 눈을 영혼의 보석으로 바꿔 놓았습니다. 용도는 두 가지입니다. 이것으로 예니쿠를 기절시킨 다음, 기절한 그의 머리 위에 올려 영혼을 가두십시오.",
    ["I was sent to Grom'gol to aid Nimboya on his quest, but... I too have reasons for being here. The Bloodscalp tribe is enemy to our tribe. Collecting trophies of our enemies gives us power over them."] = "저는 님보야의 임무를 돕기 위해 그롬골로 파견되었지만... 저에게도 이곳에 있는 이유가 있습니다. 피 두개골 부족은 우리 부족의 적입니다. 적의 전리품을 모으면 그들을 제압하는 힘이 생깁니다.",
    ["Now that you have gathered Bloodscalp trophies, I have another task for you. The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them."] = "이제 피 두개골 부족의 전리품을 모으셨으니 또 다른 임무를 드리겠습니다. 남동쪽에는 두개골쪼개기 트롤 부족이 살고 있는데, 우리는 수년째 그들과 싸우고 있습니다.",
    ["Did Lieutenant Doren want you to report back to him with that patrol information?"] = "도렌 중위가 당신에게 순찰 정보를 보고하라고 했습니까?",
    ["To have a chance against Kurzen, we need his healing support neutralized. He has gathered a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts."] = "쿠르젠을 상대할 승산을 얻으려면 그의 치유 지원을 무력화해야 합니다. 그는 정글 치료제로 병사들을 치료하고 독고사리 추출물로 우리 병사들을 중독시키는 주술사들을 대거 모았습니다.",
    ["Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was. We must not let their valiance go for naught. This crone... Charlga Razorflank..."] = "불쌍한 헤랄라스! 그리고 이 드워프... 론브로우. 얼마나 용감한 영혼이었습니까. 그들의 용기를 헛되이 만들어서는 안 됩니다. 이 노파... 찰가 레이저플랭크...",
    ["All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas."] = "이제 남은 일은 의지의 왕관을 언더시티의 샤린드라에게 전달하는 것뿐입니다. 그녀가 실바나스 여왕께 전해 드릴 것입니다.",
    ["Heavens no! Poor Rustlocke. 'Tis quite a tragedy indeed. We must not let his death pass in vain."] = "맙소사! 불쌍한 러스트록. 정말 비극입니다. 그의 죽음이 헛되이 지나가게 해서는 안 됩니다.",
    ["Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air. The crew tried so hard to save my beautiful Maiden's Folly."] = "아이고, 끔찍한 인생이로군. 지금쯤 물속 무덤에 있어야 하는데, 이렇게 불가에 앉아 신선한 공기를 마시고 있다니. 선원들이 내 아름다운 아가씨의 어리석음호를 구하려고 정말 애썼지.",
    ["Such a shame the land is in such shambles. But the Memorial came out quite well!"] = "땅이 이렇게 엉망이 되다니 안타까운 일입니다. 하지만 기념비는 아주 잘 나왔습니다!",
    ["There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers."] = "스트롬가드의 성벽 안에 강력한 흑마법사가 있다는 것은 의심할 여지가 없습니다. 이 흑마법사는 때때로 비전 마법 유물을 사용해 끔찍한 악마들을 대규모로 소환했습니다.",
    ["This is bad. It seems the Daggerspines are amassing for an attack. Naga are known for their ruthlessness in battle. They will keep attacking until I am dead."] = "큰일입니다. 대거스파인이 공격을 위해 집결하고 있는 것 같습니다. 나가는 전투에서의 무자비함으로 유명합니다. 제가 죽을 때까지 계속 공격할 겁니다.",
    ["Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered. Interrogator Vishas did this to me!"] = "의지는 자유롭지만, 더는 어둠의 여왕을 섬길 수 없습니다. 아제로스에서의 내 시간이 끝나 가는 것이 느껴집니다. 내 생명력이 부서졌습니다. 심문관 비샤스가 나에게 이렇게 했습니다!",
    ["You must defeat Myzrael before she grows in strength. If you do not, then once she has gathered enough power she will challenge her captors!"] = "미즈라엘이 힘을 키우기 전에 처치해야 합니다. 그렇지 않으면 충분한 힘을 모은 뒤 자신을 가둔 자들에게 도전할 것입니다!",
    ["A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate. She was last seen within the Syndicate controlled territory of Stromgarde."] = "신디케이트의 고위 고문이자 첩보원인 마레즈 카울의 목에 현상금이 걸렸습니다. 그녀는 마지막으로 신디케이트가 장악한 스트롬가드 지역에서 목격되었습니다.",
    ["Oh my! Oh my! There is a doom approaching. Mark me! A doom! No, I cannot speak of it...cannot utter their names or they may hear me! But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!"] = "오, 이럴 수가! 이럴 수가! 파멸이 다가오고 있습니다. 내 말을 새기십시오! 파멸입니다! 아니, 말할 수 없습니다... 그들의 이름을 입에 올릴 수 없습니다, 그들이 들을지도 모르니까요! 하지만 그들에 대해 더 알게 된다면... 어쩌면 그들을 저지할 방법을 알아낼 수 있을 겁니다!",
    ["Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention. I've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use."] = "어쩌면 로트윌의 최신 발명품이라는 다가오는 참사로부터 당신을 지켜 줄지도 모릅니다. 당신이 그를 위해 모아 온 남는 돌로 작업을 했는데, 쓸 만한 팔보호구를 만들어 드릴 수 있습니다.",
    ["The last report I received from Agmond is troubling, more so now that he's dead! He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman."] = "아그몬드에게서 받은 마지막 보고는 걱정스럽습니다. 이제 그가 죽었으니 더욱 그렇습니다! 그는 울다만 바깥 발굴 현장에서 인부들이 \"고대의 항아리\"를 발견했다고 언급했습니다.",
    ["Agmond's tracks lead from the west. It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance."] = "아그몬드의 발자국은 서쪽에서 이어집니다. 바위와 모래 위의 핏자국을 보면 드워프가 상당한 거리를 기어갔다는 것을 쉽게 알 수 있습니다.",
    ["I have the digest for you. I need not tell you to take great care with it. And to keep it far from unfriendly hands. This book holds many truths......And the truth can burn."] = "당신을 위한 요약본이 있습니다. 매우 조심해서 다루고, 적대적인 자의 손에 들어가지 않도록 하라는 말은 필요 없겠지요. 이 책에는 많은 진실이 담겨 있습니다... 그리고 진실은 불태울 수 있습니다.",
    ["After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."] = "오랜 관찰 끝에 모간스의 계획을 알아냈습니다. 그는 엘룬의 낫을 찾고 있고... 이미 찾았을지도 모릅니다! 만약 그렇다면 붉은마루 산맥과 스톰윈드 왕국이 곧 그의 어두운 힘을 느끼게 될 것입니다.",
    ["You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."] = "부관과 졸개들을 훌륭하게 처리하셨으니 마지막으로 하나만 더 부탁드리겠습니다. 세레나 블러드페더는 오래전 렉사르에게 죽임당한 블러드페더라는 하피의 자매입니다.",
    ["The thunderhawk, is a fierce beast. It is time for you to face them. You must find where it roams, and bring me its wings as proof of your successful hunt."] = "천둥매는 사나운 짐승입니다. 이제 그들과 맞설 때가 되었습니다. 그것이 배회하는 곳을 찾아서 사냥에 성공했다는 증거로 그 날개를 가져오십시오.",
    ["Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."] = "내 함대의 배가 또 한 척 노스워치 요새의 지나치게 열성적인 인간들 때문에 침몰했습니다! 그 놈들을 처리해야 합니다. 편집증 때문에 광란 상태에 빠져 있습니다.",
    ["Finally! Someone to rescue me! I can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor."] = "마침내! 누군가 나를 구하러 왔군요! 경비병을 어떻게 통과했는지 믿기지 않습니다. 테라모어의 이 광신도들은 제정신이 아닙니다. 그들은 우리 배를 침몰시키고 유일한 생존자인 나를 가두었습니다.",
    ["Following Khazgorm's plans it should be no problem to fashion an explosive charge Ah, there we go. Now, I am going to entrust you with a special task."] = "카즈고름의 계획을 따르면 폭발물을 만드는 것은 어렵지 않을 겁니다. 아, 됐습니다. 이제 당신에게 특별한 임무를 맡기겠습니다.",
    ["Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."] = "불확실함의 고통을 아실 수도, 모르실 수도 있습니다. 하지만 이것만은 아십시오. 저는 매일 해가 뜰 때부터 질 때까지 이곳에 서서 그 괴물들이 더 오지 않는지 수평선을 살피고 있습니다.",
    ["Attention! A reward is being offered for the death of the murloc \"Murkdeep\"."] = "알립니다! 멀록 \"머크딥\"을 처치하는 자에게 보상금이 제공됩니다.",
    ["Take Lok's head to Thork in the Crossroads. He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in such things."] = "록의 머리를 크로스로드의 토르크에게 가져가십시오. 그라면 말 한마디 없이도 우리 부족에게 무슨 일이 있었는지 알 것입니다... 하, 맹글투스가 그런 일을 도왔다는 건 믿지 않겠지만요.",
    ["The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons."] = "거인의 들판 너머 남쪽의 칼날갈기 가시멧돼지들은 듣기로 숙련된 대장장이가 없지만, 더 튼튼한 무기를 개발하기 시작한 모양입니다.",
    ["Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."] = "제어판의 덮개를 열자 전선, 관, 그 밖의 이상한 기계 장치들이 빽빽하게 얽혀 있는 것이 보입니다. 대부분은 실용적인 목적이 없어 보입니다.",
    ["I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"] = "가면서 배우게 되겠지요... 그리 어렵지는 않을 겁니다. 여기 버튼 몇 개와 레버 한두 개... 자, 갈 준비가 되셨습니까?",
    ["I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."] = "가져다주신 포자를 유탁액으로 만들었습니다. 이제 이것을 제 동료 약초상 자마에게 보내야 합니다. 당신이 이것을 그녀에게 가져가면 연금술 물품 비축분에서 무언가를 드릴 것입니다.",
    ["The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns!"] = "불모의 땅의 랩터는 다른 땅의 랩터보다 영리합니다. 그리고 그 영리함이 전부 뿔 속에 숨어 있는 것 같습니다!",
    ["Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."] = "헤즈룰 블러드마크는 불모의 땅에 있는 콜카르 켄타우로스의 우두머리입니다. 그는 사납고 잔혹하며 교활합니다. 그를 쓰러뜨리면 콜카르가 흩어지고 갈라져 우리에 대한 위협이 크게 줄어들 것입니다.",
    ["The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."] = "위대한 이샤 아와크는 이 물의 군주입니다. 그의 힘은 대단하고 자부심은 엄숙합니다. 해안의 인간들은 그가 많은 이들을 삼켰기에 그를 두려워합니다.",
    ["All right, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there."] = "좋습니다, 힘으로 뚫겠습니다. 준비되는 대로 여기서 나갑시다. 싸우면서 길까지 내려갈 겁니다. 그림클로가 아직 거기 있을 겁니다.",
    ["I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave. The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains."] = "저는 희귀한 버섯이 필요한 물약을 만들고 있습니다. 특정 동굴에서만 자라는 버섯입니다. 그 동굴은 동쪽, 산맥을 따라 약간 북쪽에 있는 절벽샘 폭포 뒤에 있습니다.",
    ["In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."] = "영원의 샘 전투가 끝난 뒤, 아메스아란이 파괴되고 제 사랑 아나야를 포함한 주민들이 모두 죽었다는 소식을 들었습니다.",
    ["Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine, a place of great evil in southwestern Ashenvale."] = "일크루드 마그스룰. 그래, 그자에 대해 알고 있습니다. 그는 잿빛 골짜기 남서쪽의 큰 악의 장소인 화염상흔 성소에 거처를 둔 강력한 오크 흑마법사입니다.",
    ["When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil. While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost."] = "렐루의 돌을 발견했을 때 화석의 수수께끼를 풀 열쇠라고 믿었습니다. 웰가르를 만나러 가는 길에 랩터의 습격을 받아 그 유물을 잃어버렸습니다.",
    ["So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him."] = "그러니까 탐사가가 그 신비한 화석을 다르나서스의 탐험가 연맹에 보내고 싶어 한다는 말이군요? 그 없이 어둠의 해안을 떠나는 것은 마음이 편치 않습니다.",
    ["The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!"] = "마스터의 글레이브에서 찾은 양피지는 고대 문서의 한 쪽입니다... 엘프가 쓴 것입니다!",
    ["I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock. That key is a ring, the Ring of Zoram."] = "고대 조각상의 옛 자물쇠를 열 열쇠를 찾지 못하면 그 비밀은 영원히 숨겨질 것 같아 걱정입니다. 그 열쇠는 반지, 조람의 반지입니다.",
    ["Relara's fever has passed, but she is still very weak. I do not believe time alone will give her back the strength she has lost. I believe it will take the power of a moonstone."] = "렐라라의 열병은 지나갔지만 아직 매우 약합니다. 시간만으로는 잃어버린 기력을 되찾을 수 없을 것 같습니다. 달의 돌의 힘이 필요할 것 같습니다.",
    ["Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."] = "아닐리아가 당신의 어깨에 손을 얹고 가까이 끌어당깁니다. 숨을 헐떡이며 북쪽의 아치를 가리키더니, 눈을 감고 마지막 거친 숨을 내쉬며 숨을 거둡니다.",
    ["Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep. The leader of the Outrunners is an orc named Tharil'zun--we want this orc."] = "검은바위 질주병과 변절자들이 이곳과 스톤워치 요새 사이에서 매복을 벌이고 있습니다. 질주병의 우두머리는 타릴준이라는 오크입니다. 우리는 이 오크를 원합니다.",
    ["Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."] = "이제 책 필사를 마쳤으니 원본 \"강철의 압박\"을 돌려드리겠습니다. 기다려 주셔서 감사하며, 밀턴을 보시면 오래 지체해서 미안하다고 전해 주십시오.",
    ["Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."] = "힐스브래드 전투에서 용맹하고 끈기 있게 싸우셨기에, 전투에서의 활약을 칭송하여 고위 사령부가 알아볼 수 있도록 이 표창장을 작성했습니다.",
    ["Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."] = "대마법사 아루갈은 스컬지에 맞서기 위해 늑대인간을 은빛소나무 숲으로 불러들였지만 곧바로 통제력을 잃었고, 자신이 소환한 것들 속에서 그림자송곳니 성채에서 미쳐 버렸습니다.",
    ["Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection. Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to..."] = "그림자송곳니 성채에는 제 수집품에서 매우 귀하게 여겨질 책, 우르의 서가 있습니다. 우르는 스컬지가 오기 전 달라란의 위대한 마법사였고, 다른 세계에 대한 그의 연구는 매우 가치가...",
    ["Arugal's own belt. He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."] = "아루갈 자신의 허리띠입니다. 그는 은빛소나무 숲을 구하려고 늑대인간을 소환했지만, 자신이 불러낸 것들에 둘러싸여 그림자송곳니 성채에서 정신을 잃었습니다.",
    ["Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated."] = "아루갈은 아직도 그림자송곳니 성채에 있습니다. 아루갈이 죽기 전에는 은빛소나무 숲을 어둠의 여왕의 전략적 거점이라고 주장할 수 없습니다. 그의 마법을 뿌리 뽑도록 제가 조치하겠습니다.",
    ["These deviate creatures have strange, otherworldly properties."] = "이 변종 생물들은 기이하고 이 세상의 것이 아닌 특성을 지니고 있습니다.",
    ["Hey. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar. One object of my studies are the insect-like creatures found to the south in the Field of Giants."] = "이봐. 나는 오그리마의 주인들을 위해 땅을 지켜보고 일어나는 일을 기록하라고 크로스로드로 보내졌다. 내 연구 대상 중 하나는 남쪽 거인의 들판에서 발견되는 곤충 같은 생물이다.",
    ["The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."] = "통곡의 동굴의 드루이드, 송곳니 드루이드는 이단입니다. 그들은 불모의 땅을 치유하려던 고결한 드루이드 교단의 일원이었지만, 이제는 뒤틀린 자신들의 꿈에 맞추어 그 땅을 다시 만들려 합니다.",
    ["All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready. Remember, after you've escaped, meet Terenthis back in Auberdine."] = "좋습니다... 확실하다면 몰래 빠져나가겠습니다. 준비되면 떠납시다. 탈출한 뒤에는 아우버다인의 테렌시스를 만나야 한다는 것을 기억하십시오.",
    ["So excited I am! Three little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of..."] = "정말 신나는군요! 작은 엘프 셋을 위한 작은 우리 셋! 하지만 우리의 사랑스러운 나무 껴안기 친구들은 어떻게 할까요? 그야, 맛을 보여 주자고요...",
    ["I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones."] = "저는 게렌조를 한 번 만난 적이 있는데, 눈 뜨고 보기 힘든 자입니다. 살이 썩어 가는 것처럼 보이고, 몸에 금속과 톱니바퀴를 이식했으며, 팔다리 일부를 기계로 바꿨습니다.",
    ["The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items. They devised a complex scheme to keep them from falling into the wrong hands."] = "드루이드들은 돌발톱 봉우리에 발톱 소굴을 지었고, 그곳에 강력한 물건을 많이 보관하고 있습니다. 그 물건이 잘못된 손에 들어가지 않도록 복잡한 계획을 세웠습니다.",
    ["I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains."] = "티란데 위스퍼윈드 님께서 직접 이 임무에 참여한 당신께 감사를 전하고 싶어 하실 겁니다. 겉으로는 그렇게 보이지 않을지 몰라도, 당신이 시작하도록 도운 일은 돌발톱 산맥에서 우리의 입지를 크게 강화할 수 있습니다.",
    ["As you may know, wyverns are often tamed by orcs for use as mounts. But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself."] = "아시다시피 와이번은 흔히 오크가 길들여 탈것으로 씁니다. 하지만 덜 알려진 사실은, 와이번의 독이 일부 사회에서는 그 짐승 자체보다 더 값지다는 것입니다.",
    ["it is now time for you to travel to far-off lands. You are ready. You now hunt Frostmaw, a yeti in the Alterac Mountains. He is elusive, his white coat blending into the snows of his mountain home."] = "이제 먼 땅으로 떠날 때가 되었습니다. 준비가 되었습니다. 이제 알터랙 산맥의 예티 프로스트모를 사냥하십시오. 그는 종적을 찾기 어렵고, 하얀 털이 고향 산의 눈과 어우러집니다.",
    ["There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track."] = "자, 라제릭이 원하던 일을 해 놓았습니다. 이것을 터뜨릴 때 조심하라고 전해 주십시오. 조금이라도 실수하면 앞으로 나아가는 게 아니라 선로 위의 그을린 자국이 되고 말 겁니다.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons. But he'll need true indurium ore, not just the flakes."] = "인듀리움은 열에 대한 저항력이 놀랍습니다! 피즐의 피스톤에 쓰기에 딱 맞을 겁니다. 하지만 부스러기가 아니라 진짜 인듀리움 광석이 필요합니다.",
    ["Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it."] = "가져오신 물을 쓰면 켄타우로스 유물을 붙잡고 있는 불꽃을 잠시 끌 수 있습니다. 하지만 영구적이지는 않으므로 서둘러야 합니다.",
    ["As you might know, I collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that can awaken Those Who Sleep."] = "아시다시피 저는 전승을 수집합니다. 오래된 전승, 강력한 전승. 문을 여는 전승, 그리고 잠든 자들을 깨울 수 있는 전승 말입니다.",
    ["The fight goes well. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings."] = "전투는 순조롭게 진행되고 있습니다. 우리가 악마와 그 수하들과의 싸움에서 이렇게 큰 진전을 계속 이룬다면, 대족장께서 계절이 바뀌기 전에 고향으로 돌아가게 해 주실지도 모릅니다.",
    ["At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place."] = "드디어 도움의 손길이 왔군요! 제가 이곳에 얼마나 오래 갇혀 있었는지 모르실 겁니다. 이곳 바깥을 마지막으로 본 게 언제인지 기억도 나지 않습니다.",
    ["I have not long to live... so... so... weak....the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel... But before I... d-d-die......my wife, Treshala..."] = "나는 오래 살지 못할 것이오... 그러니... 그러니... 약해... 용감한 드워프, 론브로우가... 팔핀델에게 경, 경고하러 보내졌소... 하지만 내가... 죽, 죽기 전에...... 내 아내, 트레샬라...",
    ["you helped us against the Magram. Now, help us beat the Maraudine! Kill the head of their clan, Khan Hratha! To face him, blow the Maraudine War Horn."] = "마그람에 맞서 우리를 도와주셨습니다. 이제 마라우딘을 물리치도록 도와주십시오! 그 부족의 수장 칸 흐라타를 처치하십시오! 그와 맞서려면 마라우딘 전쟁 뿔피리를 부십시오.",
    ["Now that you scared the centaur clans, it's time to bleed them. When traveling Desolace, hunt centaur. I don't care which clan you hunt. Just gather ears."] = "이제 켄타우로스 부족들을 겁먹게 했으니 피를 볼 차례입니다. 데솔레이스를 다닐 때 켄타우로스를 사냥하십시오. 어느 부족이든 상관없습니다. 귀만 모아 오십시오.",
    ["The Gelkis Khan is dead, and now the Maraudine will fall! Kill the Maraudine Khan, Hratha! To face him, blow the horn on the high bluff in the Valley of Spears."] = "겔키스 칸은 죽었고, 이제 마라우딘이 무너질 것입니다! 마라우딘 칸 흐라타를 처치하십시오! 그와 맞서려면 창의 계곡 높은 절벽에 있는 뿔피리를 부십시오.",
    ["Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done. Haha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time."] = "카르니톨의 물건을 아이언포지의 로텐에게 가져가면 일을 잘 해낸 대가를 지불할 겁니다. 하하, 조심하지 않으면 당신이 너무 마음에 들어서 우리와 상근으로 일하자고 할지도 모릅니다.",
    ["To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway."] = "보수를 받으려면 아이언포지로 돌아가 로텐 본인과 이야기해야 합니다. 어쨌든 그는 레프트위치의 소포를 치워 버리는 걸 반길 겁니다.",
    ["Serra'kis is the great water beast the naga breed in the flooded halls of Blackfathom Deeps, and the reason the lower temple is under water at all."] = "세라키스는 나가들이 물에 잠긴 검은심연의 나락 회랑에서 기르는 거대한 물짐승이며, 아래 사원이 아예 물에 잠겨 있는 이유이기도 합니다.",
    ["Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."] = "가무라는 나가가 검은심연의 나락에 두고 있는 고대의 거북으로, 그곳의 황혼의 숭배자들이 사원의 일부로 여길 만큼 오래되었습니다.",
    ["Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world."] = "혼돈의 고대 신들의 오래된 의식으로 힘을 얻은 황혼의 망치단 단원들은 어두운 후원자들의 귀환을 이루고 세상에 죽음과 공포를 퍼뜨리려 애씁니다.",
    ["Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor? I fear that the blood elves will meet a similar deformation."] = "어리석은 블러드 엘프들이 악마의 마법을 다루고 있습니다. 칼림도어의 나가와 사티로스에게 벌어진 일을 보지 못했단 말입니까? 블러드 엘프들도 비슷하게 변해 버릴까 두렵습니다.",
    ["Now there is just one more item needed to complete this device. Cog's blueprint calls for a lens of some sort. The only lens I know of that would be large enough will be very difficult to acquire."] = "이제 이 장치를 완성하는 데 필요한 물건이 하나 남았습니다. 코그의 설계도에는 일종의 렌즈가 필요하다고 되어 있습니다. 제가 아는 충분히 큰 렌즈는 구하기가 매우 어려울 겁니다.",
    ["The Scarlet Crusade's chief scholar, who guards the Monastery library and its collection rather more aggressively than a librarian should."] = "붉은십자군의 수석 학자로, 수도원 도서관과 그 소장품을 사서라면 하지 않을 만큼 훨씬 공격적으로 지키고 있습니다.",
    ["The survival of our people and lands comes at unfortunate costs. You have spilled the blood of nature's servants; many sick animals you have felled."] = "우리 종족과 땅이 살아남으려면 불행한 대가를 치러야 합니다. 당신은 자연의 종들의 피를 흘렸습니다. 병든 짐승을 많이 쓰러뜨렸습니다.",
    ["The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea. But perhaps, by studying the past, we can know what to expect and be better prepared for the unknown."] = "미래는 피할 수 없습니다! 우리는 빗방울이 대해로 떨어지듯 그것을 향해 몸을 던집니다. 하지만 어쩌면 과거를 연구함으로써 무엇을 예상해야 하는지 알고, 미지의 것에 더 잘 대비할 수 있을지도 모릅니다.",
    ["The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?"] = "대지의 고리는 역병에 걸린 우리 형제들에게 순수한 의도를 품고 있었습니다. 하지만 장로 의회의 귓가에 속삭이는 자들의 동기를 누가 알겠습니까?",
    ["Revelosh was a Shadowforge explorer who went into Uldaman looking for the origin of the dwarves, and became part of the ruin instead."] = "레벨로쉬는 드워프의 기원을 찾아 울다만에 들어간 그림자망치 탐험가였으며, 결국 유적의 일부가 되고 말았습니다.",
    ["A Gnomeregan oddity whose Use effect grants a huge burst of attack speed. Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision."] = "사용 효과로 공격 속도가 크게 폭발적으로 오르는 놈리건의 별난 물건입니다. 야성 드루이드는 이 효과 하나만으로 이것을 간직했는데, 표범 변신 중에도 작동하며 충전 횟수가 한정되어 있어 사용할 때마다 선택이 됩니다.",
    ["Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you."] = "머드 큰 오우거. 나 배고프다. 가서 물고기 때려라. 머드에게 먹을 것 가져와라. 머드 먹이거나 머드가 너 먹는다.",
    ["The head of the beast is ready to be taken off... with great force. You have shown every sign that you are able to help us with this final mighty blow."] = "괴물의 머리를 떼어낼 준비가 되었습니다... 엄청난 힘으로 말입니다. 당신은 이 마지막 강력한 일격을 도울 수 있다는 모든 징후를 보여 주었습니다.",
    ["Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it."] = "오래전 저는 아름다운 보석 장신구, 심연의 왕관을 가지고 있었습니다. 예쁠 뿐 아니라, 쓸 줄 아는 이에게는 큰 힘을 주는 물건이었습니다.",
    ["Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"] = "블라이 병장이 저에게서 훔쳐 갔습니다! 잠깐 빌리기만 한다고 했는데, 제가 아끼는 신성 자동 막대를 훔쳤습니다!! 그 막대 없이 어디에 새 우물을 파야 할지 어떻게 알겠습니까??",
    ["Wha.. What happened? The last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs."] = "뭐... 무슨 일이 있었지요? 마지막으로 기억나는 건 검은무쇠 드워프 무리에게 붙잡혀 죽기 직전까지 두들겨 맞고 이 더러운 트로그들과 함께 이곳에 던져진 것입니다.",
    ["Listen, that ring is yours, sure..."] = "들어 보십시오, 그 반지는 물론 당신 것입니다만...",
    ["No, no, no - I'm not all of the sudden saying that the ring is mine."] = "아니, 아니, 아니 - 갑자기 그 반지가 내 것이라고 말하는 게 아닙니다.",
    ["When we fled Gnomeregan, we left so much data behind! Vitally important data! I need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan."] = "놈리건에서 도망칠 때 우리는 너무 많은 자료를 두고 왔습니다! 대단히 중요한 자료입니다! 놈리건 깊숙한 곳의 고보안 단말기 매트릭스 천공기 3005-D에서 나오는 프리즘 천공 카드에 담긴 자료가 필요합니다.",
    ["It's terrible. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh. What we need are spare parts."] = "끔찍합니다. 우리의 자이로드릴 굴착기 함대를 던 모로로 옮길 부품이 충분하지 않을 겁니다. 우리에게 필요한 것은 예비 부품입니다.",
    ["I have cutting to do. I can't tell you what I'm going to cut, but... I need myself a blade. A certain blade... Some people call it a sword. I call it a swing blade."] = "저는 베어야 할 것이 있습니다. 무엇을 벨 건지는 말씀드릴 수 없지만... 칼날이 필요합니다. 특별한 칼날... 어떤 이들은 검이라고 부르지요. 저는 휘두르는 칼날이라고 부릅니다.",
    ["Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."] = "놈 기술 — 2년 전만 해도 가장 흔한 용도는 농담거리였습니다. 시대가 정말 변했습니다. 이제 그들은 우리의 모든 분쇄기 모델을 합친 것보다 더 나은 새 장비를 만들어 냈습니다.",
    ["My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!"] = "가죽 세공에 대한 제 철학은 작업이 가능한 최고 품질이어야 한다는 것, 타협은 없다는 것입니다. 품질이 중요하지 않다고 말하는 자는 던 모로의 해안가 땅을 팔려는 사람입니다!",
    ["I take pride in my leather work, and I feel it shows; quality should never be compromised. Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!"] = "저는 제 가죽 세공에 자부심이 있고, 그것이 드러난다고 생각합니다. 품질은 결코 타협해서는 안 됩니다. 품질이 중요하지 않다고 말하는 자는 대지가 비밀을 간직하지 않는다는 말도 믿게 하려 들 것입니다!",
    ["\"Here you go, the power source is safely removed and the data is preserved. Well, safe journeys and all that."] = "\"자, 받으십시오. 동력원은 안전하게 분리했고 자료도 보존되었습니다. 그럼, 안전한 여행이 되시기를 바랍니다.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure."] = "로봇에서 놈의 목소리가 다시 지직거리며 들립니다. \"OOX-17/TN을 열린 안전한 곳으로 옮겨야 긴 이륙 절차를 시작할 수 있습니다.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."] = "로봇에서 놈의 목소리가 다시 지직거리며 들립니다. \"OOX-22/FE를 열린 안전한 곳으로 옮겨야 긴 이륙 절차를 시작할 수 있습니다.",
    ["We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"] = "샤프빅을 구해야 합니다! 하이본 불길한 가지 부족 영토의 심장부에 있는 진타알로어 꼭대기까지 싸우며 올라가, 사악한 여사제 헥스에게서 샤프빅의 우리 열쇠를 얻은 다음 샤프빅을 찾아 구하십시오!",
    ["Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then."] = "제 친구 록바이터에게 돌아가는 길을 찾도록 도와주실 수 있습니까? 그가 저를 지켜보기로 했는데... 저는 가끔 헤매는 버릇이 있습니다.",
    ["I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff!"] = "방금 페랄라스에 도착했는데, 이곳 황야에 사는 고르둔니 오우거가 흥미로운 광물을 가지고 있다고 들었습니다. 그들이 무슨 일을 꾸미는지는 몰라도, 그것을 철저히 지키는 건 분명합니다!",
    ["Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you."] = "쉬기 전에 토크카르와 다시 이야기해 보십시오. 당신이 없는 동안 그가 무기 몇 개를 완성한 것 같습니다. 이곳에서의 도움에 대한 보답으로 그중 하나를 드릴 겁니다.",
    ["There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers."] = "제 고객들 사이에서는 크롤러 고기의 풍부한 맛에 대한 수요가 높습니다. 특히 거대 크롤러의 고기가 그렇습니다.",
    ["Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."] = "무기에 무이섹을 불어넣는 것은 어려운 과정입니다. 이제 필요한 재료와 당신이 잡은 생물들의 무이섹을 모두 갖추었으니 시작할 수 있습니다.",
    ["So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family."] = "그래서 지금이 그때입니까? 당신의 노력에 감사하며, 상황이 허락하지 않는다면 지금 제가 그리고 제 가족을 위해 해 주신 모든 일에 감사를 전하게 해 주십시오.",
    ["Black dragons kill many ogre. Kill Tharg's wife."] = "검은용 오우거 많이 죽인다. 타르그 아내 죽였다.",
    ["For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered."] = "당신이 한 모든 일에 대해 충분한 보상을 받을 자격이 있습니다. 델그렌에게 돌아가 아트리쿠스 나라신이 당신의 손에 잠들었고, 어두운 가닥 교단은 패배하여 흩어졌다고 전하십시오.",
    ["A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman."] = "얼마 전 저는 그림자망치 드워프들과 문제가 있었습니다. 그들은 울다만에서 나온 두 종류의 이상한 돌을 연구하라고 저를 앙고르 요새로 데려갔습니다.",
    ["The Druids of the Fang broke from Cenarius and let the Emerald Nightmare into the Wailing Caverns. These were theirs."] = "송곳니 드루이드는 세나리우스와 결별하고 에메랄드 악몽이 통곡의 동굴로 들어오게 했습니다. 이것들은 그들의 것이었습니다.",
    ["The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade."] = "이글거리는 협곡의 거미는 그림자 비단의 귀중한 공급원입니다. 아시다시피 그림자 비단은 우리 업계의 장인들이 간절히 찾는 물건입니다.",
    ["They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price. It gets worse."] = "그들은 스스로를 암시장이라 부릅니다. 적당한 값이면 팔고, 옮기고, 거래하고, 무엇이든 하는 날강도 상인들입니다. 더 나쁜 일이 있습니다.",
    ["A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."] = "칼림도어의 동료인 약초상 헬브림이 로데론 독소가 칼림도어 짐승들에게 미치는 영향을 연구하고 있습니다. 렌페렐이 보내 준 늑대 심장 표본에 크게 관심을 가질 겁니다.",
    ["This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."] = "이 두루마리는 돌발톱 봉우리의 발톱 소굴 열쇠지기인 음모가 드라이어드 린타리엘에게서 온 것입니다. 이것을 약탈한 전령과는 더 이상 연락하지 않겠지요, 헤헤. 하지만 우리는 이곳을 지켜야 합니다.",
    ["This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare."] = "이 파편에는 큰 비밀이 담겨 있습니다. 에메랄드의 꿈의 순수한 정수입니다. 하지만 이 파편에서 제가 보는 것은 꿈이 아닙니다. 이런 환영은 악몽이라 부를 만합니다.",
    ["Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."] = "부디 이것에서 오래된 유물 하나를 가져가십시오. 우리에게는 더 이상 쓸 데가 없는 물건입니다. 군단과의 싸움에서 당신에게 도움이 되기를 바랍니다.",
    ["the creation of each weapon will take some time. Additionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration."] = "각 무기를 만드는 데는 시간이 걸립니다. 또한 지옥저주의 힘은 3분에 한 번만 쓸 수 있습니다. 더럽히는 자 라젤리크와 그 수하들에 대한 약화 효과는 지속 시간이 다를 수 있습니다.",
    ["Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch. Make haste to Wyrmbog in the south of Dustwallow Marsh."] = "오닉시아의 새끼들이 용의 안개 전역에 흩어졌습니다. 더 이상의 새끼가 부화하지 못하게 해야 합니다. 서둘러 먼지진흙 습지 남쪽의 웜 늪으로 가십시오.",
    ["Big dragons come and make fire at old home. Me smart ogre."] = "큰 용 와서 옛집에 불 낸다. 나 똑똑한 오우거.",
    ["Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring."] = "이 황야에서는 킨달과 저에게 도움에 보답할 수단이 변변치 않지만, 감사를 받지 못한다고 느끼시지 않기를 바랍니다. 제 인장 반지를 받으십시오.",
    ["Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward."] = "타이모어가 대가를 치를 만한 것을 주지 않았으니, 아이언포지로 돌아가면 직접 따지시길 권합니다. 그는 신비 지구의 자기 자리에 여전히 있을 겁니다.",
    ["Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly. Ah, this is indeed a good day. Thank you for your help."] = "오그리마의 벨그롬에게 돌아가십시오. 그는 그녀의 머리를 직접 보고 싶어 할 겁니다! 우리도 곧 그곳으로 돌아갈 것입니다. 아, 정말 좋은 날입니다. 도와주셔서 감사합니다.",
    ["It... It... It was all a trap. Forgive... me. Kill the bastard... Kill him for us... for Thorius."] = "이... 이... 이건 모두 함정이었소. 용서... 해 주시오. 그 개자식을 죽여 주시오... 우리를 위해... 토리우스를 위해 죽여 주시오.",
    ["Will you assist me, mortal? Will you find the prayer to Elune? As I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person."] = "저를 도와주시겠습니까, 필멸자여? 엘룬께 올리는 기도를 찾아 주시겠습니까? 말씀드렸듯이 기도는 황금 서판에 새겨져 있었습니다. 우상을 숭배하는 이 악당들 중 하나가 몸에 지니고 있을 겁니다.",
    ["Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before!"] = "마젠 장인의 지시는 매우 분명했습니다. 매우 중요한 논문을 네더가드 요새의 감시자 마하르 바에게 전달하라는 것이었지요. 하지만 저는 저주받은 땅에 가 본 적이 없었습니다!",
    ["Now it is time to capture the essence of the avatar of Hakkar. Take the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth."] = "이제 학카르의 화신의 정수를 담을 때입니다. 학카르의 알을 아제로스 가라앉은 사원의 타락한 신의 성소로 가져가십시오.",
    ["Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain."] = "라젤리크의 소굴은 저주받은 땅에서 가장 높은 산 꼭대기에 있습니다. 소굴로 가는 유일한 방법은 산 근처의 순간이동 룬을 쓰는 것입니다.",
    ["My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."] = "저의 씨족 동료 무라 룬토템은 언데드 동맹을 돕기 위해 은빛소나무 숲으로 갔습니다. 은빛소나무 숲은 병든 숲, 죽어가는 숲이며, 무라는 그곳에 새 생명을 불어넣기를 바랐습니다.",
    ["In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious..."] = "불모의 땅에는 가시덤불이 뒤엉킨 끔찍한 곳, 가시덩굴 구릉이 있습니다. 처음 관찰했을 때는 위협이 거의 없어 보였지만, 최근 발견한 것은 훨씬 심각합니다...",
    ["I'm a scientist, but also a treasure hunter at heart! Long ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity."] = "저는 과학자이지만 마음은 보물 사냥꾼이기도 합니다! 오래전 트롤들이 이 땅을 차지하고 있을 때, 그들은 신으로 숭배하던 히드라 가즈릴라를 본뜬 장식품을 엄청나게 많이 만들었습니다.",
    ["A like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long. Tell you what, I'll fix you up a nice stew. Just need a few dig rats."] = "당신 같은 분은 이 불모의 땅에서 꽤 배가 고프시겠군요. 저는 하루 종일 굶주립니다. 이렇게 하지요, 맛있는 스튜를 끓여 드리겠습니다. 땅쥐 몇 마리만 있으면 됩니다.",
    ["It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor."] = "블랙래시와 헤마투스가 레슬로에 계속 갇혀 있도록 보장할 수 없다는 것이 분명해졌습니다.",
    ["I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead."] = "저는 한때 명예와 충성과 자부심으로 붉은십자군을 섬겼습니다. 그들의 대의가 고귀하다고 믿었습니다. 아제로스에서 언데드를 없애는 것이었으니까요.",
    ["I used to sail a ship from here all the way to Ratchet, in Kalimdor. I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!"] = "저는 이곳에서 칼림도어의 톱니항까지 배를 몰았습니다. 흠잡을 데 없는 평판을 가진 성공한 선장이었지요. 그런데... 저 저주받은 바다 거인들이 저를 망쳐 놓았습니다!",
    ["I think I can fix the samophlange, but I'm going to need the user's manual first."] = "사모플랜지를 고칠 수 있을 것 같지만, 먼저 사용 설명서가 필요합니다.",
    ["General Shandris Feathermoon would like to speak with you personally."] = "장군 샨드리스 페더문이 당신과 직접 이야기하고 싶어 합니다.",
    ["What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."] = "뭐라고요?! 아, 제가 현상금을 말했었지요? 입을 열면 이렇게 되는 법이군요. 일은 당신이 했으니, 가장 큰 보상을 받는 것이 마땅하겠지요.",
    ["In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."] = "운고로 분화구에는 치명적인 발톱을 가진 랩터가 있습니다. 그중 일부는 가끔 죽음처럼 검은 발톱 대신 하얀 발톱을 가지고 있습니다.",
    ["My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."] = "제 동생 리블리는 늘 가족에게 짐이었습니다. 우리 돈을 가져다 이런저런 계획에 낭비했지요.",
    ["My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger."] = "이 고문이 한 시간쯤 이어진 뒤 제 육체는 기능을 멈췄습니다. 그러자 그 짐승은 제 얼굴에서 결혼 코걸이를 뜯어내어 자기 손가락에 끼웠습니다.",
    ["your help has been immeasurable. The time will come, no doubt, when I'll ask for your assistance against the silithid once more."] = "당신의 도움은 헤아릴 수 없을 만큼 컸습니다. 틀림없이 언젠가 다시 실리시드에 맞서 당신의 도움을 청할 날이 올 것입니다.",
    ["Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."] = "들불숲은 한때 평화롭고 고요한 땅이었습니다... 군단이 장악하기 전까지는요. 인페르널, 파괴, 혼돈... 굴단의 해골이 이곳에서 누구도 무사하지 못하게 했습니다.",
    ["A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood."] = "사티로스의 두 번째 야영지가 북쪽의 들불숲 땅을 위협하고 있으며, 잔인한 자바릭이 이끌고 있습니다. 사악한 배신자와 사기꾼들은 들불숲 토착 생물들의 타락을 먹고 삽니다.",
    ["This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains."] = "이 부분이 가장 어려울 겁니다. 계획에 복잡한 면이 있으니까요. 여기서 북쪽으로 가면 산으로 이어지는 작은 길이 보일 겁니다.",
    ["Let me to be frank with you. I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain."] = "솔직히 말씀드리겠습니다. 저는 다르나서스의 대드루이드가 세나리온 의회의 이름과 자원을 이용해 막대한 양의 새벽곡식을 조달하는 이유에 관심이 있습니다. 아니, 걱정스럽습니다.",
    ["I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."] = "이제야 마침내 기억이 납니다... 저는 블레이즈러너와 싸우러 이곳에 왔습니다. 여정 중이었고 이것이 마지막 단계였습니다. 하지만 저는 더 이상 영웅이 아닙니다...",
    ["You'd think that being chief digger for Marshal Expeditions means I like digging. There might be worse things to do in this world... but none really leap to mind."] = "마샬 탐험대의 수석 굴착꾼이라고 해서 제가 땅 파는 걸 좋아한다고 생각하시겠지요. 이 세상에는 더 나쁜 일이 있을 수도 있습니다만... 딱히 떠오르는 건 없습니다.",
    ["Ugh... It's so hot... I was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion."] = "으... 너무 덥습니다... 이 지역을 탐사하던 중에 갑자기 더위를 견딜 수 없게 되었습니다. 열사병에 걸린 것 같습니다.",
    ["I'm making a flying machine! I got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death."] = "저는 비행 기계를 만들고 있습니다! 여기 발이 묶였고 길을 찾는 데는 완전히 젬병입니다. 그리폰이나 와이번을 타고 가젯잔으로 돌아갈 수도 있지만, 그 짐승들이 너무 무섭습니다.",
    ["The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."] = "악당 헐리 블랙브레스가 이끄는 검은무쇠 드워프들이 썬더브루 최고의 제조법 중 하나인 썬더브루 라거를 훔쳐 갔습니다. 악당들! 그렇게 훌륭한 술을 마실 자격이 없습니다! 어려운 임무를 하나 맡기겠습니다.",
    ["Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."] = "볼바는 바보입니다. 저는 그의 소중한 '증거'를 모아서 그의 목구멍에 쑤셔 넣으려 했습니다. 그는 눈먼 어릿광대입니다. 증거가 두 걸음 앞에 서 있는데도 보지 못합니다.",
    ["We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."] = "여기서 벗어나야 합니다. 보급 구역에서 제 장비를 되찾고 친구들을 풀어 주는 것을 도와주십시오. 무사히 빠져나가면 모건의 감시초소로 가서 마샬 맥스웰과 이야기하십시오.",
    ["As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives."] = "호수에 추락한 것만으로도 충분히 나쁜데, 근처 섬의 트로그들이 저를 공격하고 제 도구와 특별한 블라스텐하이머 폭약을 훔쳐 갔습니다.",
    ["I look at my undeath as a malady. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?"] = "저는 제 언데드 상태를 질병으로 봅니다. 치료만 필요한 병이지요. 하지만 그것은 은빛 여명회에게는 큰 축복이기도 합니다. 스컬지의 이교도들을 처단하는 그릇으로 언데드보다 나은 것이 있겠습니까?",
    ["I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done."] = "저는 계속 살아 숨 쉬겠다는 의지, 그 힘을 스컬지와 그들이 저지른 모든 일에 대한 끝없는 증오에서 끌어냅니다.",
    ["Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, of that I've no doubt."] = "이 편지를 스톰윈드로 가져가 말린에게 크라이튼과 제가 곧 집에 돌아간다고 전해 주십시오. 이곳에서 우리를 도와주셨으니 그가 후하게 보상할 것이라 의심치 않습니다.",
    ["We've learned that a source of furbolg corruption is from the satyr. They hold sway via talismans that they channel magic through. If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!"] = "퍼볼그가 타락한 근원 중 하나가 사티로스라는 사실을 알아냈습니다. 그들은 마법을 흘려보내는 부적으로 지배력을 행사합니다. 퍼볼그에게 구원의 기회가 있다면, 사티로스 타락자를 유인해 그 부적을 빼앗아야 합니다!",
    ["I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy..."] = "저는 리라드리스 문리버를 만나러 마에스트라 초소로 가던 길이었는데, 잠깐 여기서 낮잠을 자기로 했습니다. 에메랄드의 꿈에서 깨어난 뒤로 계속 너무 졸립니다...",
    ["The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone."] = "달샘의 물이 수정 안에 작은 뼛조각 몇 개와 턱뼈 절반이 박혀 있음을 드러냈습니다.",
    ["That beached creature is not an isolated incident here in Darkshore. There are more along the coastline and even in the water."] = "해변에 떠밀려 온 저 생물은 이곳 어둠의 해안에서 드문 일이 아닙니다. 해안선을 따라, 심지어 물속에도 더 있습니다.",
    ["I love crab. Crabs are the fruit of the sea! You can bake it, barbecue it, boil it, and broil it. They're pan fried, deep fried, and stir fried."] = "저는 게를 정말 좋아합니다. 게는 바다의 과일입니다! 굽고, 바비큐하고, 삶고, 불에 구울 수도 있지요. 팬에 볶고, 튀기고, 센 불에 볶기도 합니다.",
    ["I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her."] = "저는 키넬로리가 술집에서 하룻밤 보낸 뒤 훨씬 더 엉망인 꼴을 본 적이 있습니다. 지금 모습을 보니 그녀를 잘 지켜 주신 것이 분명합니다.",
    ["you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks."] = "당신은 지난날 우리에게 큰 도움이 되었으므로, 이제 중요한 임무를 맡기겠습니다. 그림토템 부족이 은밀한 일을 꾸미고 있습니다. 최근 몇 주 동안 정체불명의 요원 셋이 그림토템을 방문하는 것이 목격되었습니다.",
    ["But, there may be more centaur than I thought, I ask you, to fight with me against these vile assassins."] = "하지만 제가 생각한 것보다 켄타우로스가 더 많을지도 모릅니다. 이 비열한 암살자들에 맞서 저와 함께 싸워 주시기를 청합니다.",
    ["Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead."] = "이 정제되고 정화된 인센디아 가루를 천 개의 바늘 지역으로 가져가 신성한 생명의 불에 던지십시오. 그것은 죽은 자를 묻는 외딴 바늘 위, 검은구름 봉우리에 있습니다.",
    ["Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong."] = "아르낙은 우리가 결혼할 거라고 생각해요... 하지만 제가 그의 청혼을 거절하자 그날 밤 돌아와서 저를 납치했어요. 오빠가 막으려 했지만 아르낙이 너무 강했어요.",
    ["Wanted: Arnak Grimtotem Arnak the outcast is wanted for the heinous crimes of murder and kidnapping. Handsome rewards will be given to those brave enough to bring this criminal to justice."] = "현상 수배: 아르낙 그림토템. 추방자 아르낙은 살인과 납치라는 극악무도한 죄로 수배되었다. 이 범죄자를 정의의 심판대에 세울 용기 있는 자에게 후한 보상이 주어질 것이다.",
    ["You have the look of a fisherman! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?"] = "낚시꾼의 모습이군요! 저는 낚시를 좋아합니다. 평생 낚시를 해 왔지요. 가장 좋은 미끼는 껍질이 부드러운 조개살입니다. 물고기가 도저히 저항할 수 없거든요, 무슨 말인지 아시겠지요?",
    ["Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop."] = "평소 같으면 리거와 저는 콜카르 켄타우로스 곁을 지나 코도를 이끌고 갑니다. 가끔 켄타우로스의 전쟁 북소리가 들리는데, 그 소리가 들리면 우리는 멈춥니다.",
    ["We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them."] = "우리는 금광 위에 앉아 있는 겁니다, 정말이에요. 금광이요! 코도 뼈는 세상을 영원히 바꿀 겁니다... 제 고객들이 그것으로 가구도, 악기도, 심지어 폭약도 만들고 있습니다.",
    ["Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership."] = "글쎄요, 이 지역을 여행할 만큼 용감한 유일한 대상 행렬은 저에게 의지합니다. 제 코도 콤보뷸레이터로 늙고 죽어 가는 코도를 되살리고 제어하는 법을 알게 된 뒤로, 대상 주인 코르크, 리거, 그리고 제가 동업하게 되었습니다.",
    ["Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely."] = "당신이 회수한 들불숲 표본으로 만든 봉인된 점액이 여기 있습니다. 상자를 운고로 분화구로 가져가 순수한 점액을 찾으십시오... 원시 종류면 충분합니다.",
    ["Before you spoke to me, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a, and I now know these things to be the truth."] = "저와 이야기하기 전에 당신의 활약에 대해 들었습니다... 스스로를 증명하려는 꺾이지 않는 열망이 있고, 특출난 능력이 있다는 것을요. 이제 그것이 사실임을 압니다.",
    ["You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends."] = "조심스럽게 자루를 집어 들고 들불숲과 잿빛 골짜기 경계에 있는 제시르 문보우에게 돌아갈 준비를 합니다. 성기사의 유해를 친구들에게 넘기고 나면 합당한 예우를 받을 수 있기를 바랍니다.",
    ["Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside."] = "안타깝게도 들불숲에 대한 이 위협을 막을 유일한 방법은 정면 공격이라고 봅니다. 그림자 요새로 들어가는 다른 길은 없고, 저에게는 당신을 안으로 순간이동시킬 방법이 없습니다.",
    ["In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam."] = "겨울샘 계곡 북부에는 프로스트세이버 바위라는 큰 지형지물 주위에 큰 고양이들이 모입니다. 이 고양이들의 우두머리는 샤이로탐이라는 이름으로 알려져 있습니다.",
    ["While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand."] = "퍼볼그가 왜 이 이상한 물질을 먹고 있는지는 아직 거의 알지 못하지만, 일이 손쓸 수 없이 커지기 전에 막는 것이 최선이라고 생각합니다.",
    ["To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs..."] = "사실 이곳 겨울샘 계곡에는 화산이 없지만, 이 온천에는 훨씬 더 위협적인 이유가 있다고 생각합니다...",
    ["Quite impressive. The crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded."] = "상당히 인상적이군요. 진말로르의 수정은 폐허가 된 사원으로 돌아갈 수 없습니다. 하지만 과거의 악을 되돌리려는 당신의 노력이 보상받지 못하고 지나가서는 안 된다고 생각합니다.",
    ["The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch. Examining the branch reveals glyphs of a druidic nature carved into the bark."] = "타우렌 드루이드의 생명 없는 손이 놀랄 만큼 건강해 보이는 참나무 가지를 움켜쥐고 있습니다. 가지를 살펴보니 껍질에 드루이드 계열의 문양이 새겨져 있습니다.",
    ["Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal! I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted."] = "사악한 세력, 아마도 스컬지가 안도할에서 시간의 흐름을 조작했습니다! 이곳에서 시간의 흐름을 유지하고 손상된 것을 복구하려 해 보겠지만, 방해받지 않고 하려면 당신의 도움이 필요합니다.",
    ["In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak."] = "우드메인에 있는 우리는 만족합니다. 우리는 낯선 이를 좋아하지 않습니다. 우리에게는 좋지만 교역에는 좋지 않습니다. 얼마 전 드문 나이트 엘프 친구가 우드메인에 왔는데, 룬천 망토를 입고 있었습니다.",
    ["Daddy told me to give you this key. He said it opens a chest out back behind the house. He also wanted me to thank you. Did you do a favor for him?"] = "아빠가 이 열쇠를 아저씨께 드리라고 했어요. 집 뒤에 있는 상자를 열 수 있대요. 그리고 고맙다는 말도 전해 달라고 했어요. 아빠한테 도움을 준 적이 있나요?",
    ["Ok, everything is prepared and packed and ready for transport! Good luck in your journey, and make sure you tell Tinkee that she owes me!"] = "좋습니다, 모든 준비가 끝나 포장되어 운송 준비가 되었습니다! 여행에 행운이 따르기를, 그리고 팅키에게 저한테 빚졌다고 꼭 전해 주십시오!",
    ["There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts. Sounds scary, doesn't it? Well think how scary it is to the Magram!"] = "남동쪽에는 마그람 유령들이 출몰하는 뼈의 계곡이 있습니다. 무섭게 들리지요? 마그람에게는 얼마나 무서울지 생각해 보십시오!",
    ["The amount of salve made out of the reagents you brought me is good enough for ten doses. While I work with the village to try and make some more salve, I'd like for you to help us get a head start."] = "가져오신 재료로 만든 연고는 열 번 쓸 분량입니다. 제가 마을 사람들과 함께 연고를 더 만드는 동안, 우리가 먼저 시작할 수 있도록 도와주셨으면 합니다.",
    ["You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect. Go now back to your trainer, Mathrengyl Bearwalker, in Darnassus."] = "젊은 드루이드가 수생 형상을 취하기 전에 배워야 하는 필수 수업을 모두 마쳤습니다. 이제 다르나서스의 스승, 마트렌길 베어워커에게 돌아가십시오.",
    ["That's fascinating! I have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle."] = "대단히 흥미롭군요! 저는 늘 진실이 궁금했습니다... 이 지식은 꼭 공유해야 합니다! 즉시 대드루이드 판드랄 스태그헬름에게 가십시오. 다르나서스의 세나리온 의회에서 찾을 수 있을 겁니다.",
    ["The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."] = "대지의 고리는 원소를 연구하고 보존하는 데 헌신하는 주술사 집단입니다. 그들은 미친 고대 신, 고대 전설과 전승에 대해 대부분의 학자가 평생 알 수 있는 것보다 더 많은 것을 잊어버렸을 정도입니다.",
    ["Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound."] = "얼마 전, 떠돌이 오우거 대규모 무리가 타나리스에 도착했습니다. 여기서 남쪽으로 사막의 넓은 지역을 점령하고 야영지를 세웠습니다.",
    ["I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty."] = "방금 톱니항에서 이 분쇄기를 가져와서, 근무하기로 되어 있는 전쟁노래 벌목 야영지로 돌아가는 중이었습니다.",
    ["I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients."] = "저는 뱀의 보석을 당신께 맡깁니다. 이 보석을 여기서 북서쪽의 작은 섬 라나지아르 섬의 뱀 조각상 손에 놓으십시오. 그렇게 하면 고대의 서를 지키는 자가 소환됩니다.",
    ["Behold - the Hand of Iruxos. A gruesome sight indeed. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do."] = "보십시오, 이룩소스의 손입니다. 정말 섬뜩한 광경이군요. 마노로크 소굴의 악마 차원문을 쫓아내려면 이것을 지녀야 합니다... 지금 부탁드리려는 일이 바로 그것입니다.",
    ["The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."] = "쓰러진 물 정령이 이상한 물방울 구를 남겼습니다. 이 물건이 어떻게든 그 짐승에게 에너지를 공급했을 거라고 짐작합니다. 구 안에서는 썩은 듯한 형태의 물이 출렁입니다.",
    ["Hey!! Come here! My raiders and I are about to attack the Silverwing Outpost to the west. Our target is its leader, Duriel Moonfire. Scouts report the outpost is defended heavily with sentinels and warriors."] = "이봐!! 이리 와! 나와 내 약탈자들은 서쪽의 은빛날개 전초기지를 공격하려 한다. 목표는 지도자 두리엘 문파이어다. 정찰병들의 보고에 따르면 전초기지는 감시병과 전사들이 철저히 지키고 있다.",
    ["Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."] = "경고: 여기서 서쪽의 시시르 협곡에는 본인의 책임 하에 들어가십시오. 베셀레스와 그녀의 여덟 발 달린 숲의 자식들이 이 협곡을 거미줄 소굴로 차지했습니다.",
    ["We are in short supply of a few items at the Warsong lumber camp!"] = "전쟁노래 벌목 야영지에 몇 가지 물품이 부족합니다!",
    ["As you have seen, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale."] = "보셨듯이 땅은 고통받고 있지만 생명의 순환은 강력한 것입니다. 이제 우리는 우리의 몫을 해서 그것을 돕고 있습니다. 서쪽 파괴의 중심, 그을린 골짜기에 이 씨앗들을 심어야 합니다.",
    ["Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!"] = "블러드퓨리 하피의 수를 줄이는 것만으로는 충분하지 않습니다. 그들 병의 유일한 진짜 치료법은 우두머리 블러드퓨리 리퍼를 죽이는 것입니다!",
    ["Yes, imbecile, perhaps you are ready for a more involved set of missions. The albino demon bat, Duskwing, roams the countryside just north of here."] = "그래, 멍청이, 어쩌면 좀 더 복잡한 임무를 할 준비가 되었을지도 모르겠군. 알비노 악마 박쥐 황혼날개가 여기서 바로 북쪽 시골을 배회하고 있다.",
    ["Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore. I've lost entire regiments to that monster."] = "은빛 여명회 야영지 희망의 빛 예배당을 지나 노스데일 서쪽으로 가면 뚱뚱한 구더기 짐승 보렐고어가 있습니다. 저는 그 괴물 때문에 연대 전체를 잃었습니다.",
    ["another tribe of Furbolgs, the Foulweald, live southeast of Astranaar. They are not as many as the Thistlefur, but their ferocity poses a future threat."] = "퍼볼그의 또 다른 부족 폴위드가 아스트라나르 남동쪽에 삽니다. 가시털만큼 많지는 않지만 그들의 사나움은 장차 위협이 됩니다.",
    ["Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King."] = "말신은 자신이 가시덩굴 구릉 밖에 있다고 주장합니다. 이 대사는 처단되어야 합니다. 그의 임무는 리치 왕의 눈에 실패입니다.",
    ["A pit lord left behind when the Legion's invasion collapsed, still holding the Tainted Scar where the Dark Portal's blast burned the land."] = "군단의 침공이 무너졌을 때 남겨진 구덩이 군주로, 어둠의 문의 폭발이 땅을 태운 오염된 상처를 여전히 지키고 있습니다.",
    ["Ragnaros wielded this hammer as the Firelord. Reforging it means taking the Eye of Sulfuras from Ragnaros himself and setting it into the Sulfuron Hammer."] = "라그나로스는 불의 군주로서 이 망치를 휘둘렀습니다. 이것을 다시 벼리려면 라그나로스에게서 설퍼라스의 눈을 빼앗아 설퍼론 망치에 박아 넣어야 합니다.",
    ["While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished. Here's the plan: I'm going to give you ten sticks of my special compound."] = "당신이 물자를 모으는 동안, 제 부하들 일부에게 철거해야 할 스컬지 건물에 표시를 하게 했습니다. 계획은 이렇습니다. 제 특제 혼합물 폭약 열 개를 드리겠습니다.",
    ["This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."] = "이 황혼의 망치단 추종자가 계획을 완수하게 두어서는 안 됩니다. 황혼의 망치단은 자연의 정령을 이해하지 못합니다. 그들은 오래전에 패배한 혼돈과 파괴의 존재, 고대 신을 믿습니다.",
    ["A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."] = "대지 정령의 공주이자 마라우돈이 중독된 원인으로, 그 중심에 반신인 배우자 자이타르의 몸을 안고 있습니다.",
    ["Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship."] = "마라우돈 깊은 곳에는 사악한 혼돈의 존재, 공주 테라드라스가 삽니다. 고대 신과 관련된 대지의 원소 힘입니다. 오래전 그녀와 세나리우스의 첫째 아들 자이타르가 관계를 맺었습니다.",
    ["The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it."] = "테라모크의 수정 동굴은 서쪽, 마라우돈 깊숙한 곳에 있습니다... 역사가 깊은 고대의 장소입니다. 저는 그 일부를 손에 넣고 싶습니다.",
    ["A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside. Take this vial."] = "비레텅이라는 사티로스가 마라우돈의 동굴을 타락시켜 안에 있는 많은 식물의 성장을 저해했습니다. 이 약병을 가져가십시오.",
    ["You have earned reverence among the Guard. Present your insignia!"] = "당신은 경비대에서 존경을 얻었습니다. 휘장을 제시하십시오!",
    ["Rise and be honored! Present your insignia."] = "일어나 영예를 받으십시오! 휘장을 제시하십시오.",
    ["Your time has come again. You have earned a new ranking and as such, a new insignia denoting this rise in stature."] = "당신의 시간이 다시 왔습니다. 새로운 계급을 얻었고, 그에 따라 이 지위 상승을 나타내는 새 휘장을 받게 됩니다.",
    ["I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf."] = "당신이 돌아오리라고는 예상하지 못했습니다. 아아, 당신은 서리늑대의 용감하고 명예로운 병사임을 입증했습니다.",
    ["Your radiate command and power, shaman. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name."] = "당신은 지휘력과 힘을 발산하는군요, 주술사여. 서리늑대의 눈에 숭배받는 자이며, 적은 당신의 이름만 들어도 움츠러듭니다.",
    ["You have earned the Eye of Command. Present your insignia, Commander."] = "당신은 지휘의 눈을 얻었습니다. 휘장을 제시하십시오, 사령관.",
    ["your services to the Warlords surpassed all we could expect from the denizens of this world. We do not understand your people's notions of gratitude, or rewarding good works, but in this case..."] = "당신이 전쟁군주들을 위해 한 일은 이 세상의 주민들에게서 우리가 기대할 수 있는 모든 것을 뛰어넘었습니다. 우리는 당신 종족의 감사나 선행에 대한 보상 개념을 이해하지 못하지만, 이번에는...",
    ["Anyway, you should check back with me relatively soon... that is if you want to know what was in here. As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you."] = "어쨌든 비교적 가까운 시일 안에 저에게 다시 들러 보십시오... 안에 무엇이 있었는지 알고 싶다면 말입니다. 그것이 무엇인지, 정말 책인지 알아내는 대로 기꺼이 알려 드리겠습니다.",
    ["Overlord Runthak awaits your arrival in the Valley of Strength. Do not keep your public waiting, hero."] = "대군주 룬타크가 힘의 계곡에서 당신의 도착을 기다리고 있습니다. 영웅이여, 대중을 기다리게 하지 마십시오.",
    ["The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."] = "네 명의 원소 군주 중 하나인 불의 군주는 검은무쇠 드워프가 검은바위 산 아래에서 소환하기 전까지 원소 차원에 묶여 있었습니다. 그 소환이 산을 갈라 놓아 화염의 땅을 만들었습니다.",
    ["A hound handler of Ragnaros's court, who curses healing shut before the fighting starts."] = "라그나로스 궁정의 사냥개 조련사로, 싸움이 시작되기 전에 치유를 막는 저주를 겁니다.",
    ["Avast Lubber! Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!"] = "어이, 땅꾼! 투기장 지배자의 장신구 12개를 가져오면 구루바시 투기장의 그랜드마스터가 될 것이다!",
    ["You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache. The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde."] = "주박'아쉬 곤충이 모자체 야영지에 가하는 위협을 처리하는 데 두 배로 잘해 주셨습니다. 그것들의 위협은 아직 끝나지 않았으며, 호드를 대신해 마지막 임무 하나를 더 부탁드리고 싶습니다.",
    ["When doing this though, be sure to save me the water elemental cores!"] = "그렇게 하는 동안 물 정령의 핵은 꼭 저를 위해 남겨 주십시오!",
    ["I have a lead on an even BETTER source of hides, if that's even possible to believe! In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis."] = "믿기 어렵겠지만 훨씬 더 좋은 가죽 공급처에 대한 단서가 있습니다! 페랄라스 북부, 분노상흔 요새 깊은 곳에 또 다른 예티 무리가 있습니다.",
    ["The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power."] = "침략하는 스톰파이크가 이 지역의 유일한 위협은 아닙니다, 병사. 계곡의 전쟁은 두 전선에서 벌어지고 있습니다. 식인 트롤 겨울도끼도 권력을 놓고 다투고 있습니다.",
    ["Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."] = "레반터스크 마을의 내 짝, 원초 톤터스크에게 돌아가십시오. 내가 집으로 돌아간다고 전해 주십시오! 그녀가 틀림없이 보상할 것입니다.",
    ["Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."] = "우리 마을의 많은 이들처럼 저도 야생에서 사랑하는 이를 잃었습니다. 아아, 제 쌍둥이 형제 말코르였습니다. 톤터스크의 짝과 같은 습격에서 사악한 가지 부족에게 붙잡혔습니다.",
    ["You take this, mon. You take this to Aerie Peak, dead center of town by the well. You plant it! Drive it right into the ground! Show those dwarves that troll mean business!"] = "이걸 가져가시오, 친구. 이걸 둥지 봉우리, 마을 한복판 우물 옆으로 가져가시오. 거기에 심으시오! 땅에 곧장 박아 넣으시오! 저 드워프들에게 트롤이 진심이라는 걸 보여 주시오!",
    ["With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open."] = "경비대장 말코르를 잃으면서 레반터스크 경비대장 자리가 다시 비었습니다.",
    ["By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."] = "원초 톤터스크의 명령이다! 사악한 여사제 헥스와 그 수하들을 심판대에 세워라! 사악한 여사제 헥스와 아만자시 정예 근위대를 모두 처치하는 자에게는 큰 보상이 주어진다.",
    ["The following items have been stolen: *One Dark Iron Tuyere. *One Lookout's Spyglass. A reward is being offered to individuals who find and return these pilfered items."] = "다음 물품이 도난당했습니다: *검은무쇠 송풍구 하나. *망루지기의 망원경 하나. 도난당한 이 물건을 찾아 돌려주는 이에게 보상이 주어집니다.",
    ["By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed."] = "감독관 오일피스트 각하의 명령이다. 토륨 연합의 배신자 요원이자 가마솥의 검은무쇠 광재 구덩이 일꾼들의 신임 지휘관 감독관 말토리우스를 죽이고 그 증거로 머리를 가져오라.",
    ["A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."] = "알렉스트라자의 무리에 속한 붉은 용으로, 네파리안의 실험으로 망가졌습니다. 타락이 그를 완전히 삼키기 전에 죽여 달라고 부탁하며, 싸우는 동안 사과합니다.",
    ["Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."] = "데스윙의 아들로, 검은바위 산 아래에서 다섯 무리 모두의 피를 지닌 용인 오색 무리를 길러 내고 있습니다. 그 작업이 진행되는 동안 수년간 빅터 네파리우스 경으로서 스톰윈드 궁정에 있었습니다.",
    ["One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."] = "네파리안의 내부 소굴을 지키는 용 세 마리 중 하나로, 자신이 입힌 상처로 스스로를 치유하는 놈입니다.",
    ["Cut from the fang of one of Nefarian's drakes. Tanks wore it for the stun it shrugs off, not the numbers on it."] = "네파리안의 용 중 하나의 송곳니에서 깎아 낸 것입니다. 탱커들은 수치가 아니라 기절을 견디는 효과 때문에 이것을 착용했습니다.",
    ["The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."] = "네파리안의 용 세 마리 중 마지막으로, 전투가 이어질수록 그저 점점 더 분노하는 놈입니다.",
    ["The ultimate symbol of a haruspex's power is what they wear."] = "점술사의 힘의 궁극적 상징은 그들이 입는 것입니다.",
    ["We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around."] = "우리 잔달라는 드루이드의 방식을 모릅니다. 자연은 우리의 필요에 맞게 빚어지는 것이지, 그 반대가 아닙니다.",
    ["By communion with animals and givin' them up to the spirits when needed, they give us divine guidance. In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi."] = "동물과 교감하고 필요할 때 그것들을 영들에게 바침으로써 그들은 우리에게 신성한 인도를 줍니다. 과거에는 점술사의 통찰과 지혜가 구루바시 갈라진 부족들과의 전쟁에서 우리에게 우위를 주었습니다.",
    ["Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose."] = "학카르의 수석 저주술사로, 적의 영혼 조각을 묶었다가 풀어놓는 방식으로 싸웁니다.",
    ["He must be stopped! Take this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy."] = "그를 막아야 합니다! 이 신성한 끈을 가져가 우리 신들의 에너지를 전달하는 대사제들의 머리를 꿰십시오.",
    ["My delvings into the Mosh'aru Tablets bear grim news. Hakkar's true form, the god himself, can be born again through the very egg into which you captured him."] = "모샤루 석판에 대한 제 연구는 암울한 소식을 전합니다. 학카르의 진짜 모습, 신 자신이 당신이 가둔 바로 그 알을 통해 다시 태어날 수 있습니다.",
    ["One of Ysera's four green consorts, corrupted by the Emerald Nightmare and now roaming Feralas, rotting the ground it stands on."] = "이세라의 녹색 배우자 넷 중 하나로, 에메랄드의 악몽에 타락해 지금은 페랄라스를 떠돌며 서 있는 땅을 썩게 합니다.",
    ["The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing."] = "엘룬아라 호수의 물이 이 물건을 삼킨 악몽을 녹여야 합니다. 정화를 하는 동안 잠시 기다려 주십시오.",
    ["A Nightmare-corrupted green dragon who splits himself into shades rather than face a fight whole."] = "악몽에 타락한 녹색 용으로, 온전한 모습으로 싸우는 대신 자신을 그림자로 분열시킵니다.",
    ["They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson."] = "그들은 저에게 불가능한 것을 바랍니다! 스팀휘들 무역 연합은 제가 남해 해적들에게 본때를 보여 주기를 원합니다.",
    ["The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity."] = "끔찍한 전갈 모양 괴물 데스클래스프는 실리시드의 활동이 늘어나자 남쪽 산맥으로 후퇴한 것으로 여겨집니다.",
    ["We have discovered another base of operations for the Twilight's Hammer. It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus."] = "우리는 황혼의 망치단의 또 다른 작전 기지를 발견했습니다. 황혼의 질주라는 곳으로, 실리더스 북동쪽 구석에 숨겨진 동굴입니다.",
    ["I need you to venture into Hive'Regal and find what became of my dearest Natalia. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves."] = "하이브리갈로 들어가 사랑하는 나탈리아에게 무슨 일이 있었는지 알아봐 주십시오. 쉬운 일이 아닐 겁니다. 광기의 아가리로 뛰어들기 전에 반드시 돌아가서 그 드워프들과 이야기하십시오.",
    ["An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."] = "타이탄이 죽이지 않고 안퀴라즈 아래에 묻어 둔 고대 신입니다. 그 뒤로 줄곧 퀴라지에게 속삭이고 있으며, 전쟁 전체가 그가 멈추지 않았기 때문에 존재합니다.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them."] = "세나리온 요새를 위해 전투, 물류, 전술 임무를 수행하며 모으는 휘장은 장식용 이상입니다. 간직해 두는 편이 현명합니다.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."] = "바람 소환사 프라우드혼을 위해 전투, 물류, 전술 임무를 수행하며 모으는 휘장은 장식용 이상입니다. 간직해 두는 편이 현명합니다.",
    ["I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."] = "저는 엘레멘티움을 말하는 것입니다, 필멸자여. 퀴라지 황실 예복과 독성 원소를 찾아 가져오면 강력한 무기에 불어넣어 드리겠습니다.",
    ["The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe."] = "우드메인은 타락을 피한 유일한 퍼볼그 부족입니다. 하지만 이제 다른 많은 종족이 친구인지 적인지 확인하지도 않고 퍼볼그를 무작정 죽입니다.",
    ["There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."] = "바로 남서쪽에 시든숲 퍼볼그 야영지가 있습니다. 야영지에 타락이 퍼져 있으며, 그것이 문제가 되기 전에 끝내고 싶습니다.",
    ["The Timbermaw tend to stay to themselves. While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible."] = "우드메인은 자기들끼리 지내는 편입니다. 믿는 이들에게는 안전한 통행을 허락하지만, 가능하면 다른 퍼볼그 부족과는 마주치지 않으려 합니다.",
    ["The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."] = "쌍둥이 황제... 그들의 끊임없는 속삭임이 내 정신을 서서히 갉아먹고 있습니다. 내가 그들의 영역으로 더 들어가 동생 아리고스를 구할 수 없다는 걸 알고 나를 조롱합니다.",
    ["It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."] = "필멸의 종족이 입는 화려한 어깨 방어구는 용의 날개를 흉내 내려는 시도에서 시작되었다고 우리 사이에서는 전해집니다.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you."] = "가장 강력한 퀴라지는 용조차 멈칫하게 할 만한 힘을 지닌 물건을 휘두릅니다. 퀴라지의 지배의 속박과 그 밖의 소소한 재료를 가져오면 당신을 위해 강력한 장화 한 벌을 만들어 드리겠습니다.",
    ["You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."] = "내 종족에게 당신의 가치를 증명하고 싶습니까, 필멸자여? 좋습니다, 어쩌면 서로 도울 수 있겠군요. 고대 모래벌레 오우로는 전설적인 힘을 지닌 존재입니다.",
    ["The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."] = "입에 담을 수 없는 고대 신이 안퀴라즈 아래에서 서서히 잠에서 깨어납니다. 아제로스를 기다리는 끔찍한 운명은 며칠 뒤일 수도, 몇 년 뒤일 수도 있습니다. 그런 힘을 지닌 존재에게 시간은 의미가 없습니다.",
    ["The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong."] = "퀴라지와 그 하수인들은 가장 희귀하고 훌륭한 재료로 만든 물건을 휘두릅니다. 거대한 고대 생물의 뼈, 땅속 깊은 곳의 보석, 순수하고 강한 금속 말입니다.",
    ["The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities. The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings."] = "퀴라지 부관들이 착용한 반지는 그들에게 가공할 능력을 준다는 소문이 있습니다. 반지를 장식한 타락한 보석은 이론상 더 순수한 재료로 교체해 타락하지 않은 반지를 만들 수 있습니다.",
    ["I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."] = "당신이 안퀴라즈 공격을 돕고 있다는 소식을 들으니 기쁩니다. 우리의 적과 싸우는 데 도움이 될 방어 장비를 만들어 드리겠습니다.",
    ["A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."] = "끔찍한 위협이 잠들었습니다. 잔혹한 오시리안이 쓰러졌습니다. 칼림도어의 주민들이 이 승리를 알게 되면 안도할 것입니다.",
    ["I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book!"] = "알았어야 했는데. 나의 숙적 위빌 박사가 또 수작을 부렸군요! 그리고 이제 당신이 겨울샘 계곡에서 실패한 탓에 위빌 박사가 내 책을 파괴했습니다!",
    ["Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit."] = "나쁜 소식은 아직 말하지 않았던가요? 이름은 아가리입니다. 100피트 길이의 죽음과 파괴의 화신이지요. 그 사소한 사실을 깜빡한 것 같습니다.",
    ["Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it..."] = "용사여, 당신입니까? 파편을 맡은 지 천 년이 흘렀고, 나를 그것에서 해방시켜 줄 이가 일어나는 것은 가장 어두운 시간입니다...",
    ["We must use restraint against Eranikus. We are to redeem him not destroy him. Tyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction."] = "에라니쿠스에게는 자제력을 발휘해야 합니다. 우리는 그를 파괴하는 것이 아니라 구원해야 합니다. 티란데가 이 임무를 돕기 위해 이미 오고 있습니다. 용의 공격을 견뎌내고 밤의 안식처를 확실한 파멸에서 구해야 합니다.",
    ["Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."] = "퀴라지의 쌍둥이 황제로, 형제의 힘 대신 쿤의 마법의 재능을 물려받은 쪽입니다. 두 쌍둥이 중 어느 쪽도 상대와 멀리 떨어져서는 죽일 수 없습니다.",
    ["Twin emperor of the qiraji, and the stronger arm of the pair. Kill one and the other heals him, so both must fall together."] = "퀴라지의 쌍둥이 황제로, 둘 중 더 강한 팔입니다. 한쪽을 죽이면 다른 쪽이 치료해 주므로 둘 다 함께 쓰러뜨려야 합니다.",
    ["A sandworm grown enormous under the desert, surfacing only to feed."] = "사막 아래에서 거대하게 자라 먹이를 먹을 때만 지상으로 올라오는 모래벌레입니다.",
    ["A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."] = "독이 너무 강력해 싸움이 사실상 그녀의 독과의 경주가 되는 퀴라지 번식 여왕입니다.",
    ["A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."] = "전투 도중 새끼를 낳고 침입자를 벽에 던져 버리는 거대한 퀴라지 굴착 생물입니다.",
    ["The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."] = "퀴라지 제국 최고의 병사로, 자신의 명예 근위병과 함께 싸우며 그들과 떨어지기를 거부합니다.",
    ["A living mass of qiraji poison. It has to be frozen solid and then shattered, which is not how most things die."] = "퀴라지 독의 살아 있는 덩어리입니다. 단단하게 얼린 다음 부수어야 하는데, 대부분의 것이 죽는 방식과는 다릅니다.",
    ["One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."] = "하나처럼 싸우는 퀴라지 의회 세 명 중 하나입니다. 누구든 죽이면 살아남은 자들이 더 강해집니다.",
    ["The third of the qiraji council, who charges the moment the fight begins and does not stop."] = "퀴라지 의회의 셋째로, 전투가 시작되자마자 돌격하여 멈추지 않습니다.",
    ["C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."] = "쿤의 대변인입니다. 퀴라지가 믿는 모든 것은 그가 고대 신이 그렇게 말했다고 일러 준 덕분에 믿는 것입니다.",
    ["To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."] = "시간의 동굴로 가십시오, 군주여/숙녀여. 아나크로노스가 당신의 귀환을 기다리고 있습니다. 그에게 쿤의 눈을 건네십시오. 그는 틀림없이 주인의 수집품에 넣고 싶어 할 것입니다.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gloves that you wish to upgrade."] = "제 목숨을 구해 주시는 데 계속 관심을 가지시게 하려면 보상이 필요하다고 생각합니다. 개선하고 싶은 허리띠와 장갑 세트를 가져오십시오.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."] = "발탈라크의 영혼이 이 목걸이에 저장되어 있었습니다. 우리는 탐욕에 눈이 멀어 어리석게도 세 조각으로 나누었고, 어떤 저주가 기다리는지 몰랐습니다. 발탈라크의 주문을 막는 유일한 방법은 메달리온을 다시 합치는 것입니다.",
    ["I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange for a small favor."] = "저는 당신 직업의 사람들이 입는 것과 비슷하지만 훨씬 품질이 높은 방어구 한 벌을 가지고 있습니다. 작은 호의를 베풀어 주신다면 팔보호구를 평범한 것과 교환해 드리겠습니다.",
    ["That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."] = "대단한 이야기군요! 감사합니다, 그리고 관련된 모든 이들의 진심 어린 감사도 전합니다. 이제 두 눈을 감고 밤에 잠들 수 있을지도 모르겠습니다.",
    ["Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."] = "하지만 오랜 친구가 당신을 보냈다 해도 저는 호의를 함부로 베푸는 사람이 아닙니다. 우리의 거친 오우거 이웃에 대해서는 증오와 경멸밖에 없습니다.",
    ["My brother and I run the poison operations out of the manor Ravenholdt."] = "저와 형은 레이븐홀트 저택에서 독 사업을 운영합니다.",
    ["From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes."] = "쓰러진 자들의 시체에서 갑옷을 벗겨 알 수 없는 용도에 쓰기 위해 낙스라마스로 가져갑니다.",
    ["The Guardian's staff, broken and scattered. Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it."] = "수호자의 지팡이는 부서져 흩어졌습니다. 이를 재건하려면 낙스라마스에서 조각 마흔 개와 켈투자드의 받침대를 모아 메디브가 한때 그것을 보관하던 카라잔 폐허로 가져가야 합니다.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial wrists."] = "당신과 고인이 된 오마리온 덕분에, 그가 편히 잠들기를, 이제 빙하 손목보호구를 만들 수 있게 되었습니다.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"] = "어서 오십시오, 친구여. 위대한 힘을 지닌 물건과 교환하고 싶은 여명회 또는 십자군의 휘장이 있습니까?",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial cloak."] = "당신과 고인이 된 오마리온 덕분에, 그가 편히 잠들기를, 이제 빙하 망토를 만들 수 있게 되었습니다.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Polar tunic."] = "당신과 고인이 된 오마리온 덕분에, 그가 편히 잠들기를, 이제 극지 튜닉을 만들 수 있게 되었습니다.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar gloves."] = "당신과 고인이 된 오마리온(그가 편히 잠들기를) 덕분에 이제 극지 장갑을 만들 수 있게 되었습니다.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar bracers."] = "당신과 고인이 된 오마리온(그가 편히 잠들기를) 덕분에 이제 극지 팔보호구를 만들 수 있게 되었습니다.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."] = "어서 오십시오, 친구여. 위대한 힘을 지닌 물건과 교환하고 싶은 여명회 또는 십자군의 휘장이 있습니까? 경고해 두겠습니다. 여명회와의 평판이 우호적일 때의 구매에는 극도로 높은 할증금이 붙습니다.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power? I must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge."] = "어서 오십시오, 친구여. 힘을 지닌 물건과 교환하고 싶은 여명회 또는 십자군의 휘장이 있습니까? 경고해 두겠습니다. 여명회와의 평판이 우호적일 때의 구매에는 높은 할증금이 붙습니다.",
    ["You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"] = "스스로를 여명회의 영웅이라고 생각하시는군요, 그렇습니까? 우리의 가장 위대한 병사들이 켈투자드의 잡병들에게 짓밟히는 것을 본 적이 있습니다! 그렇게 아무것도 모르는 사람이 낙스라마스에서 얼마나 잘해 낼 수 있겠습니까?",
    ["A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."] = "아서스의 편에 선 아졸네룹의 지하무덤 군주로, 거미 지구의 가장 바깥 홀을 지킵니다.",
    ["A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."] = "켈투자드의 숭배자로, 추종자들을 언데드가 된 후에도 데리고 와 여전히 지휘합니다.",
    ["A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs."] = "거미 지구 깊숙한 곳에 거미줄로 매달린 거대 거미로, 스컬지가 더 이상 필요로 하지 않는 것을 먹고 자랍니다.",
    ["An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."] = "스컬지가 남긴 찌꺼기를 기워 만든 흉물로, 순수한 힘 외에는 아무 목적도 없이 만들어졌습니다.",
    ["A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."] = "일부러 반쯤 굶겨 둔 꿰맨 사냥개로, 건축물 지구에서 보내오는 것은 무엇이든 먹어 치우게 하려는 것입니다.",
    ["A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson."] = "스컬지의 새 장교들을 훈련하는 죽음의 기사입니다. 자신의 학생들이 건드리지도 못할 만큼 강한데, 그것이 바로 이 수업의 핵심입니다.",
    ["Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."] = "군사 지구에서 라주비우스와 함께하는 동료로, 자신의 죽은 자들 뒤에서 싸우며 계속 그들을 앞으로 내보냅니다.",
    ["A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."] = "역병 지구의 강령술사로, 방금 죽인 것을 되살리는 솜씨 덕분에 승진했습니다.",
    ["Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."] = "낙스라마스의 역병 시설과 자신보다 더 많은 공격대원을 죽인 분출의 복도를 지키는 자입니다.",
    ["A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."] = "역병 지구의 포자 통에서 자란 곰팡이 공포로, 생물이라기보다 손쓸 수 없이 자란 작물에 가깝습니다.",
    ["A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."] = "노스렌드에서 죽임을 당해 서리 와이번으로 되살아난 푸른 용입니다. 켈투자드의 방으로 가는 마지막 길목을 지킵니다.",
    ["Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."] = "한때 키린 토의 대마법사였던 그는 달라란을 떠나 저주받은 자들의 교단을 세우고 네르줄을 기꺼이 섬겼습니다. 안도할에서 죽임을 당해 리치로 되살아난 그는 낙스라마스의 중심에 있는 성물함에서 이곳을 다스립니다.",
    ["Here's your cask of Evershine. And again, thank you for the hunting earlier."] = "에버샤인 술통 여기 있습니다. 그리고 앞서 사냥해 주신 일에도 다시 한번 감사드립니다.",
    ["Recently, a new group of thieves has been hanging around Northshire. They call themselves the Defias Brotherhood, and have been seen across the river to the east."] = "최근 노스샤이어 근처에 새로운 도둑 무리가 어슬렁거리고 있습니다. 그들은 스스로를 데피아즈단이라 부르며, 동쪽 강 건너편에서 목격되었습니다.",
    ["The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."] = "대지 어머니의 의식은 젊은 타우렌이 썬더 블러프에서 존경을 얻기 위해 거쳐야 하는 단계입니다. 먼저 힘의 의식을 통과해야 합니다.",
    ["My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances."] = "저와 제 형 세니르는 트롤이 가하는 위협을 조사하기 위해 던 모로의 서로 다른 지역으로 파견되었습니다. 의회는 트로그 때문에 이미 손이 꽉 차 있어서 더 이상의 골칫거리는 원하지 않습니다.",
    ["Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest. According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew."] = "붉은십자군이 폴의 안식처 너머, 티리스팔 북부의 폐허가 된 탑에서 습격을 벌이고 있습니다. 우리가 가진 정보에 따르면 무자비한 지휘관 멜라체 대장이 이 사악한 무리를 이끌고 있습니다.",
    ["Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young. The Wildmane Totem is made, and your last task lies ahead."] = "당신이 겨울발굽 우물과 천둥뿔 우물을 정화했다는 이야기가 영들 사이에 오르내립니다, 젊은이. 와일드메인 토템이 만들어졌고, 당신의 마지막 임무가 앞에 있습니다.",
    ["Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\" I can't deal with losing all our caravans, so I'm just going to take matters into my own hands."] = "가즐로우가 한번 저에게 말했습니다. \"레즐락. 인생에서 알아야 할 것이 하나 있는데, 일이 제대로 되기를 바란다면 직접 하라는 거야.\" 우리 대상 행렬을 전부 잃는 건 감당할 수 없으니, 제가 직접 나서겠습니다.",
    ["My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that."] = "내 일지! 놈들이 동굴로 가져갔습니다. 그것을 가진 놈은... 피부와 얼굴에 이상한 문양이 있는 덩치 큰 짐승이었습니다. 그 이상은 제대로 보지 못했습니다.",
    ["Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw."] = "생명을 묶는 자 알렉스트라자와 영원한 노즈도르무의 축복이 없었기에 텔드랏실의 성장에는 결함이 없지 않았습니다.",
    ["You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts. We can now turn our eyes to other concerns."] = "광산에서 진전이 있는 것 같다는 소식을 들으면 기쁘실 겁니다. 당신의 노력 덕분이 적지 않습니다. 이제 다른 일들로 눈을 돌릴 수 있습니다.",
    ["Two extra attacks on a proc, on a fast axe. Warriors farmed Dire Maul for this one item and nothing else."] = "빠른 도끼로, 발동 시 추가 공격 두 번. 전사들은 이 물건 하나만을 위해 혈투의 전장을 돌았습니다.",
    ["We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us."] = "우리는 웨스트폴의 거대한 광산 깊은 곳, 문브룩의 헛간 아래에 숨겨진 곳에 있었습니다. 이 고약한 도둑놈들이 어디서 왔는지는 알 수 없습니다. 어쨌든 광산 갱도가 우리 위로 무너졌습니다.",
    ["Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened."] = "자, 이것을 받아서 그의 무덤 위에 놓아 주십시오. 어쩌면... 어떻게든 그가 제가 괜찮다는 것과, 우리 중 누구도 그날 일을 그의 탓으로 여기지 않는다는 것을 알게 될지도 모릅니다.",
    ["Stalvan Mistmantle led a life of depravity. Innocent victims died by his hand. Undoubtedly he is guilty of countless crimes. Now the lunatic threatens Darkshire."] = "스탈반 미스트맨틀은 타락한 삶을 살았습니다. 그의 손에 죄 없는 희생자들이 죽었습니다. 틀림없이 셀 수 없는 죄를 저질렀습니다. 이제 그 미치광이가 다크샤이어를 위협하고 있습니다.",
    ["I do not know why, but a festering grows within the Wetlands. Fen Creepers have risen. They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes."] = "이유는 모르겠지만 저습지 안에서 곪는 것이 자라고 있습니다. 늪 포복자가 일어났습니다. 땅 위의 병든, 열이 오른 물집이며, 열이 내리려면 처치되어 다시 습지로 가라앉아야 합니다.",
    ["Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it."] = "대담한 대릴과 머리싸움을 할 수 있다고 생각하십니까? 그럴 리가요! 물론 얼마든지 도전해 보셔도 좋습니다. 여기 당신 능력을 넘어서는 과제가 있으니 해내지 못해도 너무 낙담하지 마십시오.",
    ["Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!"] = "얼마 전, 트로그가 이 지역에 나타나기 직전에 우리는 이상한 조각상 우상을 대량으로 발견했습니다. 하지만 연구할 기회는 없었습니다. 발견 직후 트로그들이 우리를 폐허에서 쫓아냈기 때문입니다!",
    ["Now that the catapults have been burned, find and kill Chieftain Nek'rosh."] = "이제 투석기를 불태웠으니, 족장 넥로쉬를 찾아 처치하십시오.",
    ["Murlocs are becoming a problem. Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!"] = "멀록이 문제가 되고 있습니다. 더 큰 물고기 인간 무리가 에버스틸 호수 해안에 닻을 내리고 한바탕 낚시를 하고 있습니다!",
    ["ath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat. You should try your hand at boar hunting."] = "아스, 그렇습니까? 첫 시험을 마쳤다고 자부심이 터질 것 같군요, 흠? 전에 말했듯이 큰 업적은 아닙니다. 멧돼지 사냥에 도전해 보십시오.",
    ["Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate."] = "저와 다른 몇몇 전사들은 대족장에게서 던홀드에서 물건을 가져오고 이른바 신디케이트를 조사하라는 명을 받고 파견되었습니다.",
    ["The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace..."] = "펜던트요? 물론 가지셔도 됩니다... 가져가세요! 그에 대한 기억은 남기고 싶지 않습니다... 그저 제발, 제발 조용히 떠나 주십시오...",
    ["To survive, I have to be tricky! I know the recipe for flash bombs."] = "살아남으려면 교활해야 합니다! 저는 섬광탄 제조법을 압니다.",
    ["He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!"] = "이번엔 정말 큰일을 저질렀습니다! 겔리즈가 무역 군주들이 임명한 거물들을 밀어내는 것도 모자라, 이제는 가장 악명 높은 해적의 사업에 끼어들려고 합니다!",
    ["You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself. You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!"] = "당신은 거듭 실력을 증명했고, 그 임기응변은 쿠르젠 본인에 견줄 만합니다. 쿠르젠에 맞서 승리할 수 있다면... 당신이 우리 반란군 무리의 구원이 될지도 모릅니다!",
    ["The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto. Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."] = "스트롬가드 민병대가 팔콘크레스트 경과 그의 경호원 오토의 목에 현상금을 걸었습니다. 팔콘크레스트는 아라시 고원에서 신디케이트의 활동을 이끌고 있으며, 그가 죽으면 그 활동에 큰 차질이 생길 것입니다.",
    ["You serve my husband well, but he does not know why Hammerfall is under attack."] = "당신은 제 남편을 잘 섬기지만, 그는 해머폴이 왜 공격받는지 모릅니다.",
    ["Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman. It has already meant tremendous casualties for our people, but it has obviously grown worse."] = "대사 인페르누스는 울다만에서 잃어버린 유물을 찾는 그림자망치 일파를 감시하라고 라그나로스가 직접 앙고르 요새로 보냈습니다. 그것은 이미 우리 종족에게 엄청난 사상자를 냈는데, 분명히 더 악화되었습니다.",
    ["Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil."] = "탐사가 웰가르는 지금 저습지의 자기 발굴지에 원본 화석을 두고 있습니다. 렐루의 돌을 발견했을 때 저는 그것이 화석의 수수께끼를 푸는 열쇠라고 믿었습니다.",
    ["When I struggled with the Forsaken's poisons, I had a vision. I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!"] = "포세이큰의 독과 싸우며 힘들어하다가 환영을 보았습니다. 도르다닐 지하 굴의 드루이드들이 언데드에게 독살당하고... 살해당하는 환영이었습니다!",
    ["We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions."] = "늑대인간 문제는 걱정 마십시오, 우리가 통제하겠습니다. 당신 친구가 우리 숲에 들여온 이 악은 억제될 것이며, 그녀의 행동에 대해 악감정은 없습니다.",
    ["It makes them go berserk! Bring me 8 idols - I want to study them, and I want them out of Trogg hands!"] = "저것들이 광폭해지게 만듭니다! 우상 8개를 가져와 주십시오. 연구하고 싶고, 트로그의 손에서 떼어놓고 싶습니다!",
    ["Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon."] = "오그리마의 벨그롬에게 돌아가 목타르가 천 개의 바늘 지역에서 그의 명령을 잘 수행하고 있다고 전해라. 내 연구도 진행되고 있으며 곧 더 많이 알게 되기를 바란다고도 전해라.",
    ["It took a long time, but I found Reethe. He hide good for a human. Ogron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him."] = "오래 걸렸지만 리스를 찾았다. 그는 인간치고 잘 숨는다. 오그론은 그가 늪에서 너무 오래 지내 미쳤을까 걱정한다. 너는 나와 함께 가서 그에게서 답을 얻는다.",
    ["I am so lost! My wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere. Would you be so kind as to lead me back to Torta?"] = "저는 완전히 길을 잃었습니다! 아내 토르타가 저녁거리를 구해 오라고 보냈는데 어딘가에서 잘못 들어선 모양입니다. 부디 토르타에게 데려다주시겠습니까?",
    ["The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."] = "시든껍질 거미 신에게서 모은 독은 정말 대단한 발견입니다! 그 한 방울만으로 토끼를 거의 두 다스나 죽일 수 있었습니다.",
    ["If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it. She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere."] = "유물을 제 아내 베스티아에게 전해 주시면 감사하겠습니다. 그녀는 우리 공동체의 훌륭한 여사제일 뿐 아니라, 어디서도 찾기 힘든 박식한 학자 중 한 명입니다.",
    ["Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal."] = "에다나 헤이트탤런은 서쪽 폐허에 사는 북샘 하피의 여왕입니다. 그녀는 순수한 악이며, 심장이 수정이라고 들었습니다.",
    ["You dare challenge Overlord Mok'Morokk? Haw! Me crush tiny! You tell me when ready for good beating."] = "감히 대군주 모크모로크에게 도전하나? 하! 나 작은 거 부순다! 좋은 매 맞을 준비되면 말해라.",
    ["Listen well. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue."] = "잘 들으십시오. 네 개의 탑은 결코 파괴할 수 없지만, 응징의 횃불로 아주 오랫동안 불타게 할 수 있습니다. 어떤 원소나 힘으로도 끌 수 없는 불입니다.",
    ["Just one last thing you must do, soldier. I've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground."] = "병사여, 마지막으로 한 가지만 해 주십시오. 제가 마음대로 고르테쉬의 머리를 창에 꽂아 두었습니다. 이제 이 머리를 공포의 망치 바위 꼭대기로 가져가 땅에 꽂으면 됩니다.",
    ["While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north."] = "당신이 운고로를 탐험하는 동안 당신 같은 강력한 사냥꾼이 즐길 만한 다른 것들도 보았습니다. 그중 하나는 북쪽의 다른 고릴라들 사이에 있던 거대한 유인원이었습니다.",
    ["Wanted: A skilled fighter to deal with the threat of the Pterrordax that inhabit the Un'Goro Crater. Their numbers are growing, and they are becoming a menace to travelers in the area."] = "현상 수배: 운고로 분화구에 서식하는 테러닥스의 위협을 처리할 숙련된 전사. 그 수가 늘어나 이 지역 여행자들에게 위협이 되고 있습니다.",
    ["I'm going to need more samples. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure."] = "표본이 더 필요합니다. 하지만... 어떻게 말해야 할지 모르겠지만, 순수한 표본이어야 합니다. 압니다, 알아요. \"'순수'가 무슨 뜻이오, 라리스?\" 저도 잘 모르겠습니다.",
    ["The blade the Silver Hand carried against the Scourge, and the one Tirion Fordring's order was built around. Corrupted when Renault Mograine used it on his own father, Alexandros, in the Scarlet Monastery."] = "은빛 손이 스컬지에 맞서 들었던 검이자 티리온 폴드링의 교단이 중심으로 삼았던 검입니다. 르노 모그레인이 붉은십자군 수도원에서 자신의 아버지 알렉산드로스에게 사용했을 때 타락했습니다.",
    ["You look like a capable. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!"] = "유능해 보이시는군요. 혹시 돈을 벌고 싶지 않으십니까? 코르크와 저는 큰돈을 벌려고 이 대상 행렬을 시작했는데, 돈을 버는 데 위험이 따른다는 건 몰랐습니다!",
    ["Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me."] = "비블리는 자기가 데솔레이스에서 돈 버는 법을 아는 유일한 고블린이라고 생각합니다. 글쎄요, 이 지역을 여행할 만큼 용감한 유일한 대상 행렬은 저에게 의지합니다.",
    ["While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield."] = "당신이 겨울샘 계곡에서 처치한 올빼미괴수에 대한 지식은 많이 가지고 있지만, 그들이 휘두르는 마법에 대해서는 그리 박식하지 않습니다.",
    ["Mirah Chandler's song, given for finishing a chain of favours in the Barrens -- the reward players remember long after they forget the errands."] = "미라 챈들러의 노래로, 불모의 땅의 호의 연계 임무를 마치면 받는 보상입니다. 플레이어들은 심부름은 잊어도 이 보상은 오래 기억합니다.",
    ["Kill me. Before it's too late. I am Hameya. While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed. We are infected."] = "저를 죽여 주십시오. 너무 늦기 전에. 저는 하메야입니다. 줄마샤르로 가는 길에 우리 형제들과 상한 고기를 먹고... 변했습니다. 우리는 감염되었습니다.",
    ["The black dragonflight's overseer in Lower Blackrock Spire, keeping the orcs there in line on Nefarian's behalf."] = "검은바위 첨탑 하층에서 네파리안을 대신해 그곳의 오크들을 통제하는 검은용 무리의 감독관입니다.",
    ["Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge."] = "데메트리아는 대십자군의 수석 고문입니다. '이 세상의 것이 아닌' 감각 때문에 신탁이라고 불립니다. 스컬지에 맞선 십자군의 여러 승리를 성공적으로 도왔습니다.",
    ["you are a hunter worthy of our company. From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated."] = "당신은 우리 무리에 어울리는 사냥꾼입니다. 로데론의 전장에서 가장 깊은 정글에 이르기까지, 당신처럼 무기를 다루는 솜씨를 보여 준 이는 거의 보지 못했습니다.",
    ["One of Onyxia's own teeth, taken after she was finally dragged out of Stormwind's court and killed in her lair."] = "오닉시아 본인의 이빨 중 하나로, 그녀가 마침내 스톰윈드 궁정에서 끌려나와 소굴에서 죽임당한 뒤에 얻은 것입니다.",
    ["A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."] = "자신의 화염맹세 부하들에게 둘러싸여 싸우며, 그중 하나가 쓰러질 때마다 더 강해지는 라그나로스의 부관입니다.",
    ["I'm going to have to do something about the giants if I stay out here! They're certainly not good for business, now are they?"] = "내가 여기 남는다면 거인들을 어떻게든 해야 할 겁니다! 그것들은 분명 장사에 좋지 않지 않습니까?",
    ["Wouldn't ye know it, every time ol' Hansel wants to take a moment to relax and reflect upon his life, the powers that be give him another job."] = "알다시피, 늙은 한셀이 잠시 쉬며 자기 삶을 되돌아보려 할 때마다 높은 분들은 새 일을 던져 줍니다.",
    ["One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."] = "네파리안의 수호 용 세 마리 중 하나로, 소굴 바닥 위에 매달린 통로를 지킵니다.",
    ["We Zandalar prize what we wear as a symbol of accomplishment."] = "우리 잔달라는 우리가 입는 것을 성취의 상징으로 소중히 여깁니다.",
    ["You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators."] = "줄구룹에서 성공하려면, 그리고 잔달라 포식자처럼 되려면 둘 다 숙달해야 합니다.",
    ["In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe."] = "구루바시 제국이 몰락한 뒤의 어두운 시대에, 잔달라 포식자들은 자신의 솜씨로 부족의 양식을 마련했습니다.",
    ["To Whom It May Concern: If you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow. Found information about a Titan."] = "관계자 여러분께: 이 글을 읽고 있다면 저는 죽었거나 곧 죽을 것입니다. 말하기 어렵군요. 어쨌든 선원 대부분은 죽었습니다. 티탄에 대한 정보를 찾았습니다.",
    ["We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."] = "우리는 천 년 동안 가만히 앉아 있지 않았습니다. 이 짐승들이 쓸모가 다하면 동족을 잡아먹는 것을 지켜보았습니다. 그들이 우리 세계를 파괴하려고 음모를 꾸미고 계략을 짜는 것을 들어 왔습니다.",
    ["Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."] = "퀴라지의 마법은 강하고 오래되었습니다. 가장 강력한 퀴라지는 용조차 멈칫하게 할 만한 힘을 지닌 물건을 휘두릅니다.",
    ["Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"] = "최고위 퀴라지 지도자들이 착용한 속박을 가져오십시오. 그것으로 네파리안 본인의 날개보다 더 무시무시한 어깨 방어구 한 벌을 만들어 드리겠습니다!",
    ["Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."] = "그의 피부 표본과 다른 소소한 재료를 가져오면 강력한 힘을 지닌 다리 방어구를 만들어 드리겠습니다.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me an ordinary belt and a set of gloves that you wish to upgrade."] = "제 목숨을 구해 주시는 데 계속 관심을 가지시게 하려면 보상이 필요하다고 생각합니다. 개선하고 싶은 평범한 허리띠와 장갑 한 벌을 가져오십시오.",
    ["I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas."] = "지하무덤 마귀의 등껍질의 쓰임새를 알아냈습니다. 그 조각을 낙스라마스에서 잃어버린 모독된 마법 갑옷 일부와 합치면 극도로 가볍고 매우 치명적인 갑옷 한 벌을 만들 수 있습니다.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icy Scale breastplate."] = "당신과 고인이 된 오마리온(그가 편히 잠들기를) 덕분에 이제 얼음 비늘 흉갑을 만들 수 있습니다.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icy Scale bracers."] = "당신과 고인이 된 오마리온 덕분에, 그가 편히 잠들기를, 이제 얼음 비늘 팔보호구를 만들 수 있습니다.",
    ["Stormwind has abandoned us. A foul wind of depravity rustles through the plains of Westfall. This was my homeland and I will not turn my back on the citizens who choose to remain here."] = "스톰윈드는 우리를 버렸습니다. 타락의 더러운 바람이 웨스트폴 평원에 불고 있습니다. 이곳은 제 고향이고, 이곳에 남기로 한 시민들에게 등을 돌리지 않을 것입니다.",
    ["The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods."] = "노스샤이어의 데피아즈단은 삼베 가면을 쓰지만, 엘윈의 데피아즈단은 아마포를 입어서 저는 그것으로 고급 아마포 제품을 만들 수 있습니다.",
    ["If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom! Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me."] = "\"수금원\"이 우리 광산에서 금을 가져가고 있다면 그는 왕국의 것을 훔치는 것입니다! 수금원을 정의의 심판대에 세우고, 당신이 준 수거 일정표에 언급된 반지를 가져오십시오.",
    ["Help me make some Westfall Stew! Come back with the following ingredients: 3 Stringy Vulture Meat 3 Goretusk Snouts 3 Murloc Eyes 3 Okra"] = "웨스트폴 스튜를 만드는 것을 도와주십시오! 다음 재료를 가지고 돌아오십시오: 질긴 독수리 고기 3개, 피멧돼지 코 3개, 멀록 눈 3개, 오크라 3개.",
    ["Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest. A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder."] = "이 땅에 제대로 된 볼일이 없는 거친 놀들이 엘윈 숲 경계를 따라 목격되었습니다. 우리 힘만으로는 감당할 수 없을 만큼 많은 무리가 저쪽 감시탑 남쪽의 숲에 들끓고 있습니다.",
    ["I'm behind on my report, and could use your help. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in."] = "보고서가 밀려서 도움이 필요합니다. 트롤이 어디에 숨어 있는지 막 알아냈는데, 트롤이 너무 많아서 들어가기가 겁이 났습니다.",
    ["You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."] = "당신은 평범한 상황에서 포세이큰에게 잠재력을 보여 주었습니다. 이제 압박 속에서의 모습을 보겠습니다. 리치 왕의 더 정신 나간 하수인인 덜컥뼈 해골은 지금까지 맞서 온 좀비보다 더 강한 적입니다.",
    ["We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres."] = "우리 포세이큰은 리치 왕의 스컬지 군대와 전쟁 중입니다. 강령술로 일으킨 언데드 군대, 북쪽의 더러운 짐승, 고통받는 유령들과 말입니다.",
    ["Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell."] = "브릴의 상관들에게서 온 보고에 따르면 붉은십자군 요원 한 명이 붉은십자군 수도원에서 파견되어 이곳 데스넬로 보내졌다고 합니다.",
    ["While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims."] = "당신이 채집하러 나간 동안 제 서적 중 하나에서 고대의 역병이 수천 명의 무고한 희생자를 쓸어버렸다는 오래된 글을 찾았습니다.",
    ["The Scourge are trying to form a base at the Agamand Mills. If they do, then they can stage further attacks within Tirisfal. The orders have been given."] = "스컬지가 아가만드 제분소에 기지를 세우려 하고 있습니다. 만약 성공하면 티리스팔에서 추가 공격을 벌일 수 있습니다. 명령이 내려졌습니다.",
    ["The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn. Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well."] = "스톰윈드 군대가 엘윈의 멀록 잠복꾼과 채집꾼에게 현상금을 걸었습니다. 그들을 도살하고 찢어진 멀록 지느러미를 가져오면 스톰윈드 군대가 후하게 보상할 것입니다.",
    ["I was sent to the Valley to guide you, but I have discovered a growing taint here... A group that calls itself the Burning Blade has a coven here in the Valley of Trials."] = "저는 당신을 안내하라고 계곡으로 보내졌는데, 이곳에 커져 가는 오염을 발견했습니다... 스스로를 불타는 칼날이라 부르는 집단이 이곳 시련의 계곡에 소굴을 차렸습니다.",
    ["The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach."] = "검치호의 털은 독특한 회색으로 주변 숲에 섞여듭니다. 그녀가 누워 있는 것을 보니 등과 배에 깊은 열상을 입은 중상인 것을 알 수 있습니다.",
    ["There is a malevolence growing in the timberlings. We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help."] = "나무정령들 사이에 악의가 자라고 있습니다. 근원을 찾으려 하고 있지만, 찾기 전까지는... 텔드랏실을 지키기 위해 도움이 불가능한 나무정령들을 베어야 합니다.",
    ["I trust the Valley of Trials will teach you much, young. I was sent to the Valley to guide you, but I have discovered a growing taint here..."] = "시련의 계곡이 당신에게 많은 것을 가르쳐 줄 것이라 믿습니다, 젊은이. 저는 당신을 안내하려고 계곡으로 보내졌는데, 이곳에 커져 가는 오염을 발견했습니다...",
    ["I had a month's worth of dried meats salted and locked away for the cold season. Kept it locked so the bears wouldn't get it! But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker."] = "한 달 치 육포를 소금에 절여 겨울철을 위해 잠가 두었습니다. 곰이 못 먹게 잠가 두었지요! 그런데 제가 사슴 사냥을 나간 사이 그 짐승, 늙은 얼음수염이 고기 보관함째 가져갔습니다.",
    ["Teebu's blade sets things on fire for reasons no one has ever explained. It is famous for being almost useless and deeply desirable at the same time."] = "티부의 검은 아무도 설명한 적 없는 이유로 불을 붙입니다. 거의 쓸모없으면서 동시에 몹시 탐나는 물건으로 유명합니다.",
    ["By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate."] = "상급 집행관 다르탈리아의 명에 따라 남작 바르두스로 알려진 인간은 포세이큰에 대한 범죄로 수배되었다. 바르두스는 신디케이트로 알려진 조직의 고위 간부로 알려져 있다.",
    ["Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields."] = "은빛소나무 숲에 대한 초기 정찰 보고에 따르면 썩은가죽 일당이 북쪽의 오래된 농장 죽은 들판에 기지를 두고 있습니다.",
    ["You looking fer work? I might have some if you're up for a little challenge. I got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed."] = "일을 찾고 계십니까? 작은 도전을 감당할 수 있다면 제가 일감이 있을지도 모릅니다. 나가가 아키리스 갈대라고 부르는 것을 팔아 큰돈을 버는 그로이라는 친구가 있습니다. 일종의 값비싼 바다 갈대입니다.",
    ["But the power harnessed in these goggles will allow you to locate them easily. A little gnomish ingenuity goes a long way!"] = "하지만 이 고글에 담긴 힘으로 그것들을 쉽게 찾을 수 있습니다. 약간의 놈 기발함이 큰 도움이 됩니다!",
    ["Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses... Go into the Ruins of Alterac and seek out the Crushridge Warmongers."] = "이제 분쇄의 능선 오우거를 맛보셨으니, 그들의 코를 제대로 피투성이로 만들어 주십시오... 알터랙 폐허로 들어가 분쇄의 능선 전쟁광을 찾으십시오.",
    ["I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud."] = "언데드 무리가 우리를 공격할 준비를 하며 숨어 있다는 보고를 받았습니다. 이 정보로 판세를 뒤집어 먼저 공격해 그들의 작은 계획을 싹부터 잘라 버릴 수 있습니다.",
    ["Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co."] = "여행자들이 계속 돌발톱 산맥에 대해 묻습니다. 와이번, 정령을 찾든 벤처 회사와 볼일이 있든, 모험하기에 인기 있는 곳인 듯합니다.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons."] = "인듀리움은 열에 대한 저항력이 놀랍습니다! 피즐의 피스톤에 쓰기에 딱 맞을 겁니다.",
    ["You have done well. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles."] = "잘하셨습니다. 제 시험을 통과했고 제 앞의 시험도 통과했습니다. 천 개의 바늘의 도른에게 돌아가십시오.",
    ["Strength has left me. Your help is needed! Long ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."] = "기력이 다했습니다. 당신의 도움이 필요합니다! 오래전 이곳은 엘룬의 위대한 사원이었습니다. 그러나 고대 신의 타락이 땅 밑에서 스며 올라와 신성한 달샘을 오염시키면서 불행이 몰락으로 이어졌습니다.",
    ["We mages do more than just waggle our fingers and make pretty sparks! We control magic, the base fabric of our world! And that takes great care, and resolve."] = "우리 마법사는 손가락을 흔들어 예쁜 불꽃을 튀기는 것 이상의 일을 합니다! 우리는 세상의 근본 구조인 마법을 다룹니다! 그러려면 큰 주의와 결의가 필요합니다.",
    ["This world has been victim to massive mystic struggles, which tore magic currents from once stable channels. We struggle to determine the effects these changes have caused, and some of us fear the worst!"] = "이 세계는 한때 안정적이던 수로에서 마법의 흐름을 찢어낸 거대한 신비의 투쟁의 희생자였습니다. 우리는 이 변화가 일으킨 영향을 파악하려 애쓰고 있으며, 우리 중 일부는 최악을 두려워합니다!",
    ["I'll go make the wands now."] = "이제 지팡이를 만들러 가겠습니다.",
    ["Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help. Deep in the Deadmines is a functional goblin shredder."] = "놈리건이 저 비열한 트로그의 지배 아래 넘어갔습니다! 상황이 심각하지만 당신이 도울 수 있을지도 모릅니다. 데드마인 깊은 곳에 작동하는 고블린 분쇄기가 있습니다.",
    ["Naralex had a noble goal. Our great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was."] = "날라렉스에게는 고결한 목표가 있었습니다. 우리의 위대한 지도자는 에메랄드의 꿈에 들어가 이 척박한 땅을 한때의 푸른 숲으로 되살리기를 열망했습니다.",
    ["The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade."] = "유물을 모노리스에서 제거하는 순간 이퀴넥스의 지팡이 속 에너지가 사라지기 시작하는 것이 느껴집니다.",
    ["Oh, you know what? That reminds me. You wanna finish up a little job I took up while I was in Tanaris? It's easy... Krinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places."] = "아, 아시겠습니까? 그러고 보니 생각났습니다. 타나리스에 있을 때 맡은 작은 일을 마무리해 주시겠습니까? 쉽습니다... 가젯잔의 크링클 굿스틸이 이곳 이글거리는 협곡과 몇몇 다른 곳에서 나는 물건을 찾고 있었습니다.",
    ["Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil. Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine."] = "북쪽 어둠의 해안 연안에는 난파선 두 척, 은빛 새벽호와 안개 장막호가 있습니다. 얼마 전 두 배는 광활한 바다를 건너 아우버다인으로 항해하다 저주받을 멀록과 마주쳤습니다.",
    ["A human lord who traded his life for undeath and became a lich in Scholomance. Killing him takes a blade specifically made to sever the bargain."] = "생명을 언데드와 맞바꿔 스칼로맨스의 리치가 된 인간 영주입니다. 그를 죽이려면 그 계약을 끊도록 특별히 만든 검이 필요합니다.",
    ["Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures."] = "랙모어의 일지에는 그의 배가 페더문 요새로 항해하다가 바다 생물들에게 공격당한 이야기가 적혀 있습니다.",
    ["The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx. Throughout Jintha'alor you will find dark vessels of tainted blood."] = "사악한 가지 부족은 초자연적인 사나움으로 싸웁니다. 이것은 사악한 여사제 헥스의 더러운 마법의 직조 때문입니다. 진타알로어 곳곳에서 오염된 피의 검은 그릇을 볼 수 있습니다.",
    ["How can one truly hope to win against a foe that is not even really there? We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe."] = "실제로 거기 있지도 않은 적을 상대로 어떻게 진정으로 이길 수 있기를 바랄 수 있겠습니까? 우리 잔달라는 그 힘을 알기에 환영술사에게 부족 안에서 영예로운 자리를 줍니다.",
    ["For you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power. For this, I will give you arm wraps our illusionists use to weave their spells."] = "우리 환영술사의 방식을 알려면 줄구룹으로 가서 선택된 힘의 귀감을 가져오십시오. 그 대가로 우리 환영술사들이 주문을 엮을 때 쓰는 팔 보호대를 드리겠습니다.",
    ["Legend states that their ancient robes never looked the same twice. I will give you an illusionist's robe..."] = "전설에 따르면 그들의 고대 로브는 두 번 같은 모습을 한 적이 없다고 합니다. 환영술사의 로브를 드리겠습니다...",
    ["There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz. Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole."] = "아탈학카르 가라앉은 사원 깊은 곳에 모르파즈라는 녹색 용이 있습니다. 몇 해 전 그는 대담한 매복으로 저를 압도하고 제 견습생을 통째로 삼켰습니다.",
    ["I can make you a protective item that'll be of assistance in the fight against our enemy. I shall need a Qiraji drape, which I'll resize for you of course."] = "우리 적과 싸우는 데 도움이 될 방어 장비를 만들어 드릴 수 있습니다. 퀴라지 망토가 필요한데, 물론 당신에게 맞게 크기를 조절해 드리겠습니다.",
    ["Well met. I've something that might interest you. I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality."] = "반갑습니다. 관심을 가지실 만한 물건이 있습니다. 당신 직업의 사람들이 입는 것과 비슷하지만 훨씬 품질이 높은 방어구 한 벌을 가지고 있습니다.",
    ["While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire."] = "대부분의 책은 솔직히 말해 쓰레기로 가득했지만 보석 같은 것도 있었습니다. 그중 한 권에는 대마법사에게 어울리는 방어구 한 벌, 서리불꽃의 제작법이 기록되어 있었습니다.",
    ["Now that my crop is saved, take this Grape Manifest to Brother Neals. He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes."] = "이제 제 작물이 구해졌으니 이 포도 목록을 닐스 수사에게 가져가십시오. 그는 노스샤이어의 음식과 음료 저장고를 관리하는데, 신선한 포도가 있다는 소식에 기뻐할 겁니다.",
    ["My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills."] = "제 친구이자 동료 공성 병기 조종사인 모리 힐델브가 언덕에서 길을 잃었습니다.",
    ["After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache."] = "지도를 신중하게 살펴본 뒤, 당신이 발견한 것이 강모 부족 전쟁족장이 나라체 야영지를 장기간 포위하려는 계획임을 깨닫습니다.",
    ["My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite."] = "제 할아버지는 마즈라나체라는 도보 괴수와 싸운 이야기를 들려주셨습니다. 악마 같은 붉은 눈, 면도날처럼 날카로운 발톱, 독이 있는 이빨에 대해서요.",
    ["Take this Nether Gem to my old comrade Bethor. It will let us communicate... and I have much to tell him."] = "이 황천 보석을 제 오랜 동료 베토르에게 가져가십시오. 이것으로 소통할 수 있고... 그에게 할 말이 많습니다.",
    ["you are a with proven interest in the security of Northshire. You are now tasked with the protection of the surrounding Elwynn Forest."] = "당신은 노스샤이어의 안전에 대한 관심이 입증된 분입니다. 이제 주변 엘윈 숲을 지키는 임무를 맡게 됩니다.",
    ["He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."] = "그를 생포하려는 모든 시도는 실패했습니다. 스톰윈드 군대는 이 놀에게 후한 현상금을 걸었습니다.",
    ["Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat."] = "많은 사냥꾼이 유명한 악어를 사냥하러 모단 호수로 이끌립니다. 의류나 방어구용 악어 가죽을 찾는 상인도 늘 있고, 그 고기 맛을 즐기는 이들도 있습니다.",
    ["Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed. Aye, the Dark Iron dwarves are a devilish breed."] = "제 병사 중 많은 이가 던 모드르 전투에서 죽었습니다. 제 형제도 탄돌 다리의 서쪽 다리가 파괴되었을 때 목숨을 잃었습니다. 그래요, 검은무쇠 드워프는 악마 같은 족속입니다.",
    ["Hail. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire."] = "안녕하십니까. 서쪽 경계를 차지한 거미들을 보셨을지도 모르겠습니다. 이 여덟 발 달린 위협은 우리가 감당하기 벅차고, 사령관은 다크샤이어에서 이렇게 먼 곳에 보낼 인력이 없습니다.",
    ["My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga."] = "스톰윈드 도시 경비대의 제 예전 스승이 얼라이언스 최고 사령부가 나가가 가하는 위협을 우려하기 시작했다고 알려 왔습니다.",
    ["But complications have arisen. A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol."] = "하지만 문제가 생겼습니다. 현지 오우거 무리가 그롬골 남동쪽 미즈자 폐허를 점령했습니다.",
    ["I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain."] = "저는 당신과 모을 수 있는 모든 이에게 저를 풀어 주리라는 믿음을 겁니다. 위대한 하늘갈기 왕 무클라가 저를 사로잡고 있습니다. 그는 이 섬의 짐승들을 지휘하며, 짐승들은 이 사슬의 도움으로 제 뜻과 달리 저를 여기 붙잡고 있습니다.",
    ["Curses! That swab Maury put a lock on his foot, and I can't open it! His loot's inside the foot, and that's what he owes me! We need to find the key to open the lock."] = "빌어먹을! 그 얼간이 모리가 발에 자물쇠를 채워서 열 수가 없습니다! 약탈품이 발 안에 있는데, 그게 그가 저에게 빚진 것입니다! 자물쇠를 열 열쇠를 찾아야 합니다.",
    ["Blast the nerve of Firallon! He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us. The Bloodsail Buccaneers will pay for their carelessness."] = "피랄론의 뻔뻔함이란! 크리스탈 호수에서 작은 배도 못 모는 주제에 우리에게 맞서 함대 전체를 이끌다니. 피의 돛 해적단은 부주의의 대가를 치를 겁니다.",
    ["The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released."] = "빛이 서서히 사라지고, 돌 칼집에 담겨 있던 검 트롤칼라르가 풀려났습니다.",
    ["O'Breen led the ships into the cove. We were certain this is where the treasure could be found. The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower."] = "오브린이 배들을 만으로 이끌었습니다. 우리는 보물이 여기 있다고 확신했습니다. 하빈저호는 무사히 정박했지만, 어리석음호와 은빛소나무의 영혼호가 다가가자 조수가 빠지기 시작했습니다.",
    ["The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily."] = "보물은 너무 오래 해저에 있어서 보석이 두꺼운 돌로 굳어 버렸습니다. 하지만 이 고글에 담긴 힘으로 그것들을 쉽게 찾을 수 있습니다.",
    ["It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal."] = "방어 시설과 그 밖에 필요한 것을 만들 재료를 구하지 못하면 이곳에서는 힘든 일이 될 겁니다. 이 지역 오우거들은 고철이 풍부한 것 같더군요.",
    ["The Syndicate in Stromgarde do battle with our contingent of militia there."] = "스트롬가드의 신디케이트가 그곳의 우리 민병대 병력과 전투를 벌이고 있습니다.",
    ["I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again."] = "저도 이곳을 빠져나갈 생각을 해야겠습니다. 여기서 벌어진 일의 소문이 윗선에 퍼지는 데는 오래 걸리지 않을 것이고, 그들이 저를 다시 만나는 것을 좋아하지 않을 것이 분명합니다.",
    ["The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken. Far south of the Barrens lies a land known as Thousand Needles."] = "블러드퓨리는 제압되었습니다. 하지만 조치를 취하지 않으면 곧 다시 모일 것입니다. 불모의 땅 훨씬 남쪽에는 천 개의 바늘이라는 땅이 있습니다.",
    ["Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own."] = "델그렌이 저에게 아우버다인의 감시병 스타브리즈에게 전갈과 보급품을 전달해 달라고 부탁했지만, 혼자 떠나는 것은 내키지 않습니다.",
    ["Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals."] = "이 아즈레토크 경이라는 자에 대해 아는 바는 없지만, 모린의 의견에 동의합니다. 그를 막아야 합니다. 특히 불타는 칼날에 영향력을 얻어 자신의 목적을 이루려 한다면 더욱 그렇습니다.",
    ["Please help! These creatures are going to eat me! Help me out of here, and I'll give you a great treasure! It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know."] = "제발 도와주세요! 이 생물들이 저를 잡아먹으려 합니다! 여기서 구해 주시면 큰 보물을 드리겠습니다! 스토나드 북쪽 늪의 제 야영지에 있는데, 저만 아는 요령으로 열 수 있는 금고에 잠겨 있습니다.",
    ["Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all."] = "대장간으로 가서 이 일을 시작해 보는 건 어떻습니까? 저는 한동안 당신이 올 것에 대비해 준비해 왔으니 오래 걸리지 않을 겁니다.",
    ["Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that. He'll send word to Ironforge to let my Jordan know that he has nothing to fear."] = "부디 두토리안에게 돌아가 제가 당분간 안전하다고 전해 주십시오. 그것은 당신과 교회 덕분입니다. 그는 아이언포지로 전갈을 보내 제 조던이 걱정할 것 없다는 것을 알게 할 겁니다.",
    ["Thanks again for your help. Here's a bottle of Steamwheedle bilge rum. Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."] = "다시 한번 도와주셔서 감사합니다. 여기 스팀휘들 선창 럼주 한 병입니다. 맥킨리에게 가져가면 그가 무법항 술에 대한 미친 믿음을 마침내 버릴 수 있을 겁니다.",
    ["A plain plate glove that became famous for its random enchants -- the of Strength roll is a 7.9% chance and was worth chasing over guaranteed epics for years."] = "무작위 마법 부여로 유명해진 평범한 판금 장갑입니다. 힘의 부여가 나올 확률은 7.9%였고, 몇 년 동안 확정 에픽보다 쫓아다닐 가치가 있었습니다.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure."] = "로봇에서 놈의 목소리가 다시 지직거리며 들립니다. \"OOX-09/HL을 열린 안전한 곳으로 옮겨야 긴 이륙 절차를 시작할 수 있습니다.",
    ["With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache. Perhaps he or someone there can make further sense of what the gnolls are up to."] = "놀의 작전 계획을 입수했으니 이제 남은 일은 그 계획을 모자체 야영지의 하도켄 스위프트스트라이더에게 가져가는 것뿐입니다. 어쩌면 그나 그곳의 누군가가 놀이 무엇을 꾸미는지 더 잘 파악할 수 있을 겁니다.",
    ["Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home."] = "저 비겁한 바보 모크모로크가 권력에 취해 있고, 타르그가 슬픔과 복수의 악마와 씨름하며 부족장 자리를 놓고 다투는 동안, 우리 옛 고향에 대한 공격의 근원을 밝히는 데 신경 쓰는 사람은 저뿐인 것 같습니다.",
    ["What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."] = "악몽을 쫓아 가라앉은 사원에 들어갔다가 스스로는 나오지 못한 녹색 용의 잔해입니다.",
    ["I'll tell you what. If you give me those unfired gauntlets, I will teach you how to make a set all your own."] = "이렇게 하겠습니다. 구워지지 않은 건틀릿을 주시면 당신만의 세트를 만드는 법을 가르쳐 드리겠습니다.",
    ["For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become?"] = "오랫동안 저는 대십자군의 꼭두각시였습니다. 붉은십자군이 변해 버린 것에 맞서 싸울 이유가 무엇이 있었겠습니까?",
    ["A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."] = "깊은 불의 용암 사냥개로, 경비 짐승으로 길러지며 라그나로스의 부관들이 먹입니다.",
    ["Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere! I was able to gather most of the pages but many are still strewn about the jungle."] = "모든 것이 순조로웠는데, 강한 돌풍이 야영지를 휩쓸어 페이지를 사방으로 흩어 버렸습니다! 대부분의 페이지를 모았지만 많은 부분이 아직 정글 곳곳에 흩어져 있습니다.",
    ["Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem. Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand."] = "안타깝게도 이 뚱뚱한 손가락 문제 때문에 예전처럼 매질을 할 수가 없습니다. 아시겠지만 이곳의 기후와 낮은 기압이 제 손가락을 부풀게 합니다.",
    ["Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."] = "네파리안의 최고 결과물입니다. 모든 용 무리의 숨결을 동시에 품은 머리 둘 달린 오색 공포입니다.",
    ["They imbue their breastplates with powerful mojo. If their beliefs falter in the face of the enemy, their breastplate will not."] = "그들은 흉갑에 강력한 모조를 불어넣습니다. 적 앞에서 믿음이 흔들린다 해도 흉갑은 흔들리지 않습니다.",
    ["Your beliefs are alien to us, heathen. Ancient Zandalar were once branded as heretics."] = "당신의 믿음은 우리에게 낯섭니다, 이교도여. 고대 잔달라는 한때 이단으로 낙인찍혔습니다.",
    ["Heathens have a place in the tribe. Heathens are freethinkers of Zandalar."] = "이교도에게도 부족 안에 자리가 있습니다. 이교도는 잔달라의 자유사상가입니다.",
    ["One of Hakkar's high priests, who returns to his feet twice before he stays down."] = "학카르의 대사제 중 하나로, 완전히 쓰러지기 전에 두 번 다시 일어서는 자입니다.",
    ["A green dragon of Ysera's flight, turned by the Nightmare and hunted across Feralas ever since."] = "이세라의 무리에 속한 녹색 용으로, 악몽에 돌아서 이후 페랄라스 곳곳에서 사냥당해 왔습니다.",
    ["The gems that adorn Qiraji idols would work quite well, as their quality is superior. Bring me the ring and idols and I'll create a powerful ring for you."] = "퀴라지 우상을 장식한 보석은 품질이 뛰어나 잘 쓰일 것입니다. 반지와 우상을 가져오면 강력한 반지를 만들어 드리겠습니다.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gauntlets that you wish to upgrade."] = "제 목숨을 구해 주시는 데 계속 관심을 가지시게 하려면 보상이 필요하다고 생각합니다. 개선하고 싶은 허리띠와 건틀릿 세트를 가져오십시오.",
    ["You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas."] = "쓰러진 우리 영웅들의 잔해는 낙스라마스 군주들의 시체에서 찾을 수 있습니다.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icy Scale gauntlets."] = "당신과 고인이 된 오마리온(그가 편히 잠들기를) 덕분에 이제 얼음 비늘 건틀릿을 만들 수 있습니다.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate."] = "당신과 고인이 된 오마리온(그가 편히 잠들기를) 덕분에 이제 얼음 파멸 흉갑을 만들 수 있습니다.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets."] = "당신과 고인이 된 오마리온 덕분에, 그가 편히 잠들기를, 이제 얼음 파멸 건틀릿을 만들 수 있습니다.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers."] = "당신과 고인이 된 오마리온(그가 편히 잠들기를) 덕분에 이제 얼음 파멸 팔보호구를 만들 수 있습니다.",
    ["This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune."] = "그녀가 곤경에 처하더라도 이것이 최소한 더 오래 해로부터 지켜 줄 것입니다. 엘룬에 대한 의무를 마치면 이곳에 있는 나에게 돌아오십시오.",
    ["Normally I put forth a small challenge to followers of the Light to test their skill."] = "보통 나는 빛을 따르는 자들의 실력을 시험하기 위해 작은 시험을 냅니다.",
    ["You be ready for your first test. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops."] = "첫 번째 시험을 치를 준비를 하게. 칼날 언덕 남쪽, 마을 바로 바깥에서 우리 병사 하나가 프라우드무어의 옛 병력 일부와 싸우다 부상을 입었다네.",
    ["Our power comes from darkness and shadow, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts."] = "우리의 힘은 어둠과 그림자에서 나오지만, 그것만이 그대의 역할은 아닙니다. 그대는 치유의 기술을 아는 데도 가치가 있음을 인정했습니다.",
    ["But to blow the horn, you need a mouthpiece. To get a mouthpiece, kill Maraudine centaur."] = "하지만 뿔나팔을 불려면 주둥이 부분이 필요합니다. 주둥이 부분을 얻으려면 마라우딘 켄타우로스를 처치하십시오.",
    ["You secure the sealed testing kit for the journey back to the Undercity. Apothecary Zinge waits for you and the sealed field testing kit there."] = "당신은 봉인된 시험 도구를 챙겨 언더시티로 돌아갑니다. 약제사 징게가 그곳에서 당신과 봉인된 현장 시험 도구를 기다리고 있습니다.",
    ["The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe."] = "잔달라의 고해 사제들은 모두 독특한 어깨 망토를 두르며, 이는 그들이 부족의 수호자임을 나타냅니다.",
    ["Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe."] = "구루바시가 몰락한 직후, 우리 잔달라는 부족 내부의 악 때문에 마지막 패배에 거의 굴복할 뻔했습니다.",
    ["We Zandalar invest power in those who speak with the authority of divinity."] = "우리 잔달라는 신성의 권위로 말하는 자들에게 힘을 부여합니다.",
    ["The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity. Bring me the desecrated remnants of the departed along with reagents of purification and you shall know faith."] = "전장에서 마지막 숨을 거둔 불쌍한 영혼들 — 존엄을 포함한 모든 것을 빼앗겼습니다. 망자들의 더럽혀진 유해를 정화의 재료와 함께 가져오십시오. 그러면 믿음을 알게 될 것입니다.",
    ["I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave."] = "저는 그림자 숲에서 그림자실 동굴에 사는 거미줄 거미를 관찰하러 왔습니다.",
    ["I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key."] = "타잔의 가방을 여는 일은 그대에게 맡기겠습니다. 안에 든 것을 가지고 저에게 돌아오십시오. 잠금 장치가 복잡하니 열쇠를 구하는 편이 가장 쉬울 것입니다.",
    ["The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel."] = "잔달라 광인의 귀중한 튜닉도 예외는 아닙니다. 그들이 끌어낼 수 있는 혼돈과 광기의 원초적인 힘을 뿜어냅니다.",
    ["One of Zandalar's legendary madcaps was Khar'vaxal the Cracked."] = "잔달라의 전설적인 광인 중 하나는 금 간 카르박살이었습니다.",
    ["The madcaps of Zandalar are similar to rogues, but above all else they embrace madness..."] = "잔달라의 광인은 도적과 비슷하지만, 무엇보다도 광기를 받아들입니다...",
    ["The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."] = "영혼약탈자는 아탈라이 사제들이 줄구룹으로 불러낸 피의 신입니다. 그는 자신을 숭배하는 자들의 피를 먹는데, 그것은 그들이 예상하지 못한 부분이었습니다.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you."] = "가장 강력한 퀴라지는 용조차 망설이게 할 만한 힘을 지닌 물건을 다룹니다. 퀴라지의 명령의 속박과 기타 소량의 재료를 가져오면 강력한 장화를 만들어 드리겠습니다.",
    ["If you want Bonescythe made, you're going to have to supply the materials."] = "뼈낫을 만들고 싶다면 재료를 직접 준비해야 합니다.",
    ["Death Knight Darkreaver lords over the Great Ossuary in the Scholomance. He threatens to twist the spirit realm to do his own bidding, and he must be stopped!"] = "죽음의 기사 암흑추적자는 스칼로맨스의 대납골당을 지배합니다. 그는 영혼의 세계를 뒤틀어 자신의 뜻대로 부리려 하니, 반드시 저지해야 합니다!",
    ["The augurs of the Zandalar all wear a distinctive chest piece called a hauberk."] = "잔달라의 점술사들은 모두 갑주 윗도리라 불리는 독특한 가슴 보호구를 입습니다.",
    ["Bring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us. Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!"] = "줄구룹 안에 있는 힘의 귀감을 제물로 가져와 그대의 가치를 우리에게 증명하게. 그렇게 하면 우리 점술사들이 쓰는 허리띠를 주지 — 강력한 모조가 깃든 것이라네!",
    ["They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people. As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe."] = "그들은 주술사가 아니다. 사람들에게 저주를 거는 게 아니라 뼈를 던지거나 잎을 읽어 통찰을 얻는 데 시간을 쓰지. 샤먼인 그대는 이미 점술의 힘에 대해 조금은 알 것이다. 우리 잔달라는 그들이 부족에게 주는 통찰을 소중히 여긴다.",
    ["Hail! I can tell by your demeanor that you've seen and done much in this world. Yet I'm willing to wager you haven't seen a piece of armor like this."] = "인사드립니다! 그대의 태도를 보니 이 세상에서 많은 것을 보고 겪으셨음을 알겠습니다. 그래도 이런 방어구는 보지 못하셨을 것이라 장담합니다.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the amulet back together."] = "발탈락의 영혼은 이 부적에 보관되어 있었습니다. 우리는 탐욕에 사로잡혀 어리석게도 그것을 세 조각으로 나누었고, 앞에서 기다리는 저주를 알지 못했습니다. 발탈락의 주문을 멈출 유일한 방법은 부적을 다시 합치는 것입니다.",
    ["A truly amazing story! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past."] = "정말 놀라운 이야기로군요! 감사드립니다. 이 일에 관련된 모든 이들의 진심 어린 감사도 확실히 전합니다. 그대의 노력으로 우리는 과거의 실수에서 벗어났습니다.",
    ["You've proven to be a very reliable individual. As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance."] = "그대는 매우 믿음직한 사람임을 증명했습니다. 이 곤경을 그대가 헤쳐 나가게 도와주리라 믿지만, 그대의 활약에 걸맞게 보상하는 것이 현명하겠지요.",
    ["For now I will exchange your belt and gauntlets."] = "지금은 그대의 허리띠와 건틀릿을 교환해 드리겠습니다.",
    ["Bring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don."] = "쓰러진 자들의 유해를 정화 재료와 함께 가져오면 대지분쇄자는 그대의 것이 될 것입니다.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial gloves."] = "그대와 오마리온 덕분에, 그가 평안히 잠들기를, 이제 빙하 장갑을 만들 수 있게 되었습니다.",
    ["I hear Lord Wishock enjoyed his beverage. You have served us well. The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you."] = "위쇼크 경이 음료를 즐기셨다고 들었습니다. 그대는 우리에게 큰 도움이 되었습니다. 그대 덕분에 스톰윈드의 흑마법사들은 방해받지 않고 우리의 길을 수행할 수 있을 것입니다.",
    ["Even fragmented, they still possess the powers of the demons trapped inside. The orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps."] = "부서졌어도 그것들은 여전히 안에 갇힌 악마의 힘을 지니고 있습니다. 소란룩의 구체는 두 조각으로 깨졌고, 그중 하나는 다시 쪼개져 검은 심연의 나락에서 황혼의 망치단 수행사제들이 사용했습니다.",
    ["I will put the robe together for you now. It will take but a few moments. Do not go far."] = "이제 그대를 위해 로브를 짜 맞추겠습니다. 잠시면 됩니다. 멀리 가지 마십시오.",
    ["I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb."] = "지금 바로 구체를 만들고 새 악마를 그 안에 불어넣는 작업을 시작하겠습니다. 끝나면 지팡이나 구체 중 원하는 형태로 선택할 수 있습니다.",
    ["I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck."] = "켄타우로스의 습격을 받은 우리 대상에서 살아남은 사람은 저뿐입니다! 희귀하지만 강력한 표범이 제 가장 좋은 장치를 지키고 있는데, 그것이 그 녀석의 목에 걸려 있습니다.",
    ["The prison is ready. Now for the most difficult portion of this task. You must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison."] = "감옥이 준비되었습니다. 이제 이 임무에서 가장 어려운 부분입니다. 이 수정 감옥을 사용하여 더럽혀진 흉터에서 파멸의 수호병 사령관 한 명을 찾아 포획해야 합니다.",
    ["Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal."] = "크로시우스는 북동쪽 부서진 흉터 골짜기에 무더기로 쓰러져 있습니다. 이 지옥불을 가져가 그의 유해에 사용하십시오. 이 불이 쓰러진 거대 지옥불정령을 되살릴 것입니다.",
    ["Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further. Through an ancient and arcane ritual, they allow a demon to enter their being."] = "흑마법사는 악마를 다루며 위험한 길을 걷지만, 우리 악마 숭배자들은 거기서 한 걸음 더 나아갑니다. 고대의 비전 의식을 통해 그들은 악마가 자신의 존재 안으로 들어오도록 허락합니다.",
    ["The demoniac seeks to embody power outright, not just possess it."] = "악마 숭배자는 힘을 그저 소유하는 것이 아니라 아예 구현하려 합니다.",
    ["The ultimate symbol of power amongst the tribe is the garb we wear in battle. A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric."] = "부족 내에서 힘의 궁극적인 상징은 우리가 전투에서 입는 복장입니다. 악마 숭배자의 로브는 고급 룬천과 가공할 모조를 하나의 직물로 융합했습니다.",
    ["My pet is almost done. Now I just need something to stuff it with. Only the voodoo feathers from the trolls in the sunken temple will do. They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro."] = "내 애완동물이 거의 다 되었네. 이제 속을 채울 것만 있으면 돼. 가라앉은 사원의 트롤들이 지닌 부두 깃털이어야만 하지. 그들의 이름은 가셔, 미잔, 졸로, 후쿠, 줄로르, 로로라네.",
    ["I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us."] = "나는 겉치레하지 않겠다, 구더기여. 역병의 심장 물건들이 품은 어둠은 우리 둘 다 파멸시킬 수도 있다.",
    ["Hey. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan. They just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe."] = "이봐. 이 근처에서 조심해. 검은무쇠 드워프들이 사방에 있어 — 그림자단조로 일족 같았어. 내가 일하던 발굴 현장을 방금 습격했어 — 우리 책임자 해머토를 포함해서 거의 모두가 죽었어.",
    ["Talk to my friend, Furen Longbeard, in the Dwarven District of Stormwind. He's the best shieldsmith you'll ever meet, and he owes me a big favor."] = "스톰윈드 드워프 지구에 있는 내 친구 푸렌 롱비어드를 찾아가십시오. 그는 당신이 만날 최고의 방패 장인이고, 나에게 큰 빚을 졌습니다.",
    ["The Whirlwind Axe comes from an elemental trial a warrior has to complete alone. Three weapons come from the same chain and you keep only one."] = "소용돌이 도끼는 전사가 혼자서 완수해야 하는 정령의 시련에서 나옵니다. 같은 연계 퀘스트에서 무기 세 개가 나오며 하나만 가질 수 있습니다.",
    ["One of three weapons from the same solitary warrior trial. Choosing it means giving up the axe and the staff for good."] = "같은 전사 단독 시련에서 나오는 세 무기 중 하나입니다. 이것을 선택하면 도끼와 지팡이는 영영 포기해야 합니다.",
    ["Burlguard sent you, did he? Yes, I have spare weapons around here, but first I have a task for you... A while ago a Defias villain Dead-tooth Jack tricked me."] = "벌가드가 보냈다고? 그래, 여기 여분의 무기가 있긴 한데, 먼저 자네에게 부탁할 일이 있네... 얼마 전 데피아즈단 악당 죽은이빨 잭이 나를 속였지.",
    ["To pass this trial, you must travel south to the Field of Giants. There you will find a host of crawling, insect creatures. They are new to the Barrens and I do not like what they herald."] = "이 시련을 통과하려면 남쪽 거인의 들판으로 가야 한다. 거기서 기어 다니는 곤충 같은 생물 무리를 보게 될 것이다. 그것들은 불모의 땅에 새로 나타났고, 나는 그것들이 예고하는 것이 마음에 들지 않는다.",
    ["I will give you a weapon, but first you must aid me. The Razormanes to the northwest came into my camp a few nights past."] = "무기를 주겠지만, 먼저 나를 도와줘야 해. 북서쪽의 칼갈기 부족이 며칠 전 밤에 내 야영지에 쳐들어왔다.",
    ["A crafted helm that outlived several tiers of raid gear. Its plans were the thing guilds actually fought over."] = "여러 단계의 공격대 장비보다 오래 살아남은 제작 투구. 길드들이 실제로 다툰 것은 그 설계도였습니다.",
    ["Son of Blackhand and the last warchief of the Dark Horde, still holding Blackrock Spire long after the rest of the Horde moved on."] = "블랙핸드의 아들이자 검은 무리의 마지막 대족장으로, 나머지 호드가 떠난 뒤에도 오랫동안 검은바위 첨탑을 지키고 있습니다.",
    ["The vindicator's symbol of power is the breastplate."] = "정의의 수호자의 힘의 상징은 흉갑입니다.",
    ["Wreak havoc on the minions of evil. Zul'Gurub must taste Zandalar vengeance."] = "악의 수하들에게 혼란을 일으켜라. 줄구룹은 잔달라의 복수를 맛보아야 한다.",
    ["Vengeance is power. The Zandalar vindicator is such power."] = "복수는 힘이다. 잔달라의 수호자가 바로 그런 힘이다.",
    ["A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."] = "퀴라지에게 부려지는 돌 거인으로, 자신과 싸우는 모든 이의 마나를 빨아들이고 가득 차면 돌로 변합니다.",
    ["During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes."] = "낙스라마스에서 스컬지와 싸우는 동안 더럽혀진 성벽 조각과 전쟁에 찢긴 판금 파편을 발견하거든 저에게 가져오십시오. 영웅들이 입는 방어구를 만들어 드리겠습니다.",
}) do text[k] = v end
